// Üretilen dosya: tool/ozgun/uret.py. Genel Kültür · Dinler tarihi ve inanç gelenekleri (tarafsız, bilgi düzeyinde) (orta).
const ozCulture7Orta = <(String, String, List<String>, String)>[
  ('Bir öğrenci \'Tanrı ve evren aynı şeydir; her şey Tanrı\'dır\' diyen bir filozofun görüşünü sınıflandırmak istiyor. Bu görüş hangisine girer?', 'Panteizm', ['Deizm', 'Düalizm', 'Agnostisizm'], 'Panteizm, Tanrı ile evreni özdeş sayar. 17. yüzyılda Spinoza bu görüşün en bilinen savunucularındandır.'),
  ('Eski bir toplumda insanlar başka tanrıların varlığını reddetmiyor, ancak yalnız kendi kabilelerinin tanrısına ibadet ediyor. Bu inanç biçimine ne ad verilir?', 'Henoteizm', ['Monoteizm', 'Ateizm', 'Animizm'], 'Henoteizm, başka tanrıların varlığını reddetmeden tek bir tanrıya bağlılığı öne çıkarır; Max Müller Veda dinini anlatırken bu terimi kullanmıştır.'),
  ('Bir topluluk, ustanın yaptığı küçük bir tahta heykelciğin kendi içinde koruyucu bir güç taşıdığına inanıp ona saygı gösteriyor. Bu inanç din biliminde hangi terimle anlatılır?', 'Fetişizm', ['Totemizm', 'Mistisizm', 'Ekümenizm'], 'Fetiş, doğaüstü güç taşıdığına inanılan nesnedir; terim Portekizce \'feitiço\' (büyülü nesne) sözcüğünden gelir.'),
  ('\'Tabu\' sözcüğü din biliminde hangi anlamda kullanılır?', 'Kutsal ya da tehlikeli sayıldığı için yasaklanan şey', ['Bir topluluğun ortaklaşa ve belirli günlerde yaptığı kurban töreni', 'Rahiplerin giydiği tören giysisi', 'Ataların ruhlarına sunulan adak yemeği'], 'Tabu, Polinezya dillerinden gelir; kutsallığı ya da tehlikesi nedeniyle yasaklanmış olanı anlatır ve din bilimine James Cook\'un yolculuklarından sonra girmiştir.'),
  ('Fransız sosyolog Émile Durkheim, dinin temelinde hangi ayrımı görmüştür?', 'Kutsal ile kutsal olmayanın (profan) ayrımını', ['İyi tanrı ile kötü tanrının ayrımını', 'Ruhban sınıfı ile sıradan halk arasındaki ekonomik ayrımı', 'Doğu ile Batı dinlerinin ayrımını'], 'Durkheim, 1912 tarihli \'Dinî Hayatın İlkel Biçimleri\' adlı eserinde dini, kutsal ile profan arasındaki ayrım üzerinden tanımlamıştır.'),
  ('Max Weber\'in \'Protestan Ahlakı ve Kapitalizmin Ruhu\' adlı eserinin ana savı hangisidir?', 'Kalvinist çalışma ahlakının kapitalizmin gelişimine katkı sağladığı', ['Dinin yalnız yoksul sınıfların teselli aracı olduğu', 'Protestanlığın bilimsel devrimi tamamen engellediği', 'Katolik kilisesinin ticareti yasakladığı için Avrupa ekonomisinin çöktüğü'], 'Weber, Kalvinist çevrelerde disiplinli çalışma, tasarruf ve dünyevi başarının ahlaki değer kazanmasının modern kapitalizmin ruhunu beslediğini ileri sürmüştür.'),
  ('Büyü, din ve bilimi karşılaştıran \'Altın Dal\' (The Golden Bough) adlı ünlü eserin yazarı kimdir?', 'James Frazer', ['Mircea Eliade', 'Rudolf Otto', 'William James'], 'İskoç antropolog Sir James George Frazer\'ın \'Altın Dal\'ı ilk kez 1890\'da yayımlanmış, dünya çapındaki büyü ve dinî uygulamaları karşılaştırmıştır.'),
  ('Bir ziyaretçi büyük bir katedrale girdiğinde hem ürperdiğini hem de karşı konulmaz bir hayranlık duyduğunu anlatıyor. Rudolf Otto bu tür kutsal deneyimi hangi kavramla adlandırmıştır?', 'Numinous', ['Hiyerofani', 'Anima', 'Nirvana'], 'Otto, Latince \'numen\' (tanrısal güç) sözcüğünden türettiği \'numinous\' kavramıyla kutsalın hem korkutan hem büyüleyen gizem olarak deneyimlenmesini anlatmıştır.'),
  ('Bir köyde sıradan görünen bir kayanın, üzerinde bir ermişin göründüğüne inanıldığı için kutsal sayılması, Mircea Eliade\'nin hangi kavramıyla açıklanabilir?', 'Hiyerofani', ['Teodise', 'Eskatoloji', 'Senkretizm'], 'Eliade, Yunanca \'hieros\' (kutsal) ve \'phainein\' (göstermek) sözcüklerinden \'hiyerofani\' terimini kullanarak bir taşın, ağacın ya da mekânın kutsalı açığa vurmasını anlatmıştır.'),
  ('İbrahimî geleneklerde Hz. İbrahim\'in iki oğlu hangi topluluklarla ilişkilendirilir?', 'İsmail Araplarla, İshak İsrailoğullarıyla', ['İsmail Romalılarla, İshak Perslerle', 'İsmail Mısırlılarla, İshak Yunanlılarla', 'İsmail Fenikelilerle, İshak Babillilerle'], 'Geleneksel anlatıda Araplar soylarını İsmail\'e, İsrailoğulları ise İshak ve onun oğlu Yakup\'a dayandırır.'),
  ('Yahudilerin kutsal kitabı Tanah\'ın adı nasıl oluşmuştur?', 'Üç bölümünün (Tora, Neviim, Ketuvim) baş harflerinden', ['Kitabı derleyen hahamın adından', 'Kudüs\'teki bir tepenin adından', 'İbranicede \'kutsal kitap\' anlamına gelen tek ve eski bir sözcükten'], 'Tanah, Tora (Öğreti), Neviim (Peygamberler) ve Ketuvim (Yazılar) bölümlerinin baş harfleri olan T-N-K\'den oluşan bir kısaltmadır.'),
  ('Yahudilikte sözlü geleneğin yazıya geçirilmiş ilk derlemesi olan Mişna ile onun üzerine yapılan tartışmalardan (Gemara) oluşan büyük külliyat hangisidir?', 'Talmud', ['Midraş', 'Kabala', 'Siddur'], 'Talmud, Mişna ve Gemara\'dan oluşur; Kudüs Talmudu ve daha kapsamlı sayılan Babil Talmudu olmak üzere iki derlemesi vardır.'),
  ('Yahudilikte Tanrı\'nın tekliğini bildiren ve \'Dinle ey İsrail\' diye başlayan temel dua hangisidir?', 'Şema', ['Kadiş', 'Amida', 'Kol Nidre'], 'Şema Yisrael, Tesniye 6:4\'ten alınan ve Tanrı\'nın tekliğini ilan eden temel inanç duasıdır; sabah ve akşam okunur.'),
  ('Sinagogda Tora metni hangi biçimde saklanır ve okunur?', 'El yazması parşömen tomar olarak', ['Basılı ciltli kitap olarak', 'Taş tabletlere kazınmış olarak', 'Ahşap levhalara boyanmış metinler olarak'], 'Sinagog törenlerinde okunan Tora, özel eğitimli bir kâtibin (sofer) parşömene elle yazdığı tomardır (Sefer Tora).'),
  ('Kudüs\'te sabah duasına katılan bir adam, siyah deri kayışlarla sol koluna ve alnına içinde Tora pasajları bulunan küçük kutucuklar bağlıyor. Bu kutucukların adı nedir?', 'Tefilin', ['Tallit şalı', 'Mezuza', 'Şofar'], 'Tefilin, kayışlarla kol ve alına bağlanan siyah deri kutucuklardır; içlerinde Şema dahil Tora pasajları vardır.'),
  ('Sinagogda dua eden bir adam, omuzlarına dört köşesinde püsküller sallanan beyaz, çizgili bir şal alıyor. Bu dua şalının adı nedir?', 'Tallit', ['Kipa', 'Tefilin', 'Parohet'], 'Tallit dua şalıdır; dört köşesindeki tzitzit püskülleri, Sayılar kitabındaki buyruğa göre emirleri hatırlatmak içindir.'),
  ('Bir sinagogda sekiz kişi toplanmış, ancak bazı duaları cemaatle okuyabilmek için iki kişi daha beklemeleri gerektiği söyleniyor. Bekledikleri asgari topluluğun adı nedir?', 'Minyan', ['Kahal', 'Yeşiva', 'Beth din'], 'Geleneksel Yahudilikte belli duaların cemaatle okunabilmesi için en az on yetişkinden oluşan bir minyan gerekir.'),
  ('Yahudi geleneğinde Talmud ve dinî hukuk eğitimi verilen okula ne ad verilir?', 'Yeşiva', ['Sinagog', 'Mikve', 'Kibbutz'], 'Yeşiva, öğrencilerin özellikle Talmud ve dinî hukuku çalıştığı geleneksel Yahudi eğitim kurumudur.'),
  ('Yahudiliğe geçmek isteyen bir kadın, dinî mahkemenin kabulünden sonra doğal su kaynağından beslenen özel bir havuza tamamen giriyor. Bu havuzun adı nedir?', 'Mikve', ['Minyan', 'Bima', 'Sukka'], 'Mikve, ritüel temizlik için içine tamamen girilen özel havuzdur; din değiştirme ve evlilik öncesi arınmada kullanılır.'),
  ('Bir Yahudi ailenin oğlu 3 Mart\'ta doğmuştur. Geleneğe uygun olarak sekizinci günde yapılacak brit mila hangi tarihte gerçekleşir? (Doğum günü birinci gün sayılır.)', '10 Mart', ['11 Mart', '8 Mart', '13 Mart'], 'Yahudi geleneğinde doğum günü birinci gün sayılır; sekizinci gün 3 + 7 = 10 Mart olur. Brit mila, Tekvin\'deki antlaşmaya dayanarak bu günde yapılır.'),
  ('Bir Yahudi düğününde gelin ve damat, dört direğe gerilmiş bir örtünün altında durarak nikâhlarını kıydırıyor. Yeni yuvayı simgeleyen bu örtüye ne ad verilir?', 'Hupa', ['Bima', 'Sukka', 'Tallit'], 'Hupa, çiftin kuracağı yeni yuvayı simgeleyen dört direkli bir örtüdür; nikâh töreni bunun altında yapılır.'),
  ('Seferad Yahudilerinin İspanyolcadan gelişen geleneksel dili hangisidir?', 'Ladino (Yahudi İspanyolcası)', ['Yidiş (Yahudi Almancası)', 'Aramice', 'Amharca'], 'Ladino (Judeo-Espanyol), Seferad Yahudilerinin eski İspanyolcaya dayanan dilidir; Yidiş ise Aşkenazların Almancaya dayalı dilidir.'),
  ('18. yüzyılda Polonya-Ukrayna bölgesinde Baal Şem Tov\'un öncülüğünde doğan, coşkulu dua ve mistisizmi öne çıkaran Yahudi akımı hangisidir?', 'Hasidizm', ['Reform Yahudiliği', 'Karaizm', 'Siyonizm'], 'Hasidizm, Israel ben Eliezer\'in (Baal Şem Tov) öğretileriyle ortaya çıkmış, sevinçli ibadeti ve manevi rehber (rebbe) bağlılığını öne çıkarmıştır.'),
  ('Talmud\'u ve sözlü geleneği reddedip yalnız yazılı Tanah\'ı bağlayıcı sayan Yahudi topluluğu hangisidir?', 'Karaylar', ['Hasidikler', 'Seferadlar', 'Ortodokslar'], 'Karaizm, 8-9. yüzyılda ortaya çıkmış ve rabbani sözlü geleneği kabul etmemiştir; Kırım ve Litvanya\'daki Türkçe konuşan Karaylar bu inancı sürdürür.'),
  ('19. yüzyıl Almanya\'sında ortaya çıkan, ibadette yerel dili kullanmayı ve dinî kuralları çağa göre yorumlamayı savunan akım hangisidir?', 'Reform Yahudiliği', ['Hasidizm', 'Karaizm', 'Ultra-Ortodoks Yahudilik'], 'Reform Yahudiliği 19. yüzyılda Almanya\'da gelişmiş, ibadette Almancayı kullanmış ve geleneksel kuralların birçoğunu bağlayıcı saymamıştır.'),
  ('Babil sürgününden Yahudilerin Kudüs\'e dönmesine izin veren Pers hükümdarı kimdir?', 'Büyük Kiros', ['Dârâ', 'Kserkses', 'Kambises'], 'MÖ 539\'da Babil\'i alan Pers kralı Büyük Kiros, Yahudilerin geri dönüp mabedi yeniden yapmalarına izin vermiştir.'),
  ('Kudüs\'teki Ağlama Duvarı (Batı Duvarı) neden Yahudiler için özel önem taşır?', 'İkinci Mabet\'i çevreleyen avlu duvarından kalan bir bölüm olduğu için', ['Musa\'nın On Emir\'i aldığı yer olduğu için', 'Davud peygamberin mezarının üzerine yapıldığına inanıldığı için', 'İlk sinagogun duvarı olduğu için'], 'Batı Duvarı, Herodes\'in genişlettiği Mabet Tepesi\'nin istinat duvarının kalıntısıdır; yıkılan mabede en yakın erişilebilir nokta olduğu için en kutsal dua yeridir.'),
  ('Matta, Markos ve Luka İncillerine birbirine çok benzeyen anlatımları nedeniyle verilen ortak ad hangisidir?', 'Sinoptik İnciller', ['Apokrif İnciller', 'Pastoral Mektuplar', 'Katolik Mektuplar'], 'Bu üç İncil olayları büyük ölçüde aynı sırayla ve benzer ifadelerle anlattığı için \'birlikte bakılabilen\' anlamında sinoptik diye adlandırılır; Yuhanna farklı bir yapıdadır.'),
  ('Pavlus\'un Hristiyanlığı Yahudi olmayanlara yaymasının erken Hristiyanlık açısından en önemli sonucu hangisidir?', 'Hristiyanlığın Yahudi bir mezhep olmaktan çıkıp evrensel bir dine dönüşmesi', ['Hristiyanlığın yalnız Kudüs\'le sınırlı kalması', 'Yeni Ahit\'in Latince yazılması', 'Kilisenin hemen Roma İmparatorluğu\'nun resmî dini hâline gelmesi ve devletle birleşmesi'], 'Pavlus, sünnet gibi Yahudi kurallarını Yahudi olmayan inananlar için şart koşmayarak Hristiyanlığın Yahudi olmayanlar arasında hızla yayılmasını sağlamıştır.'),
  ('İngilizcede kuşkucu kişi için kullanılan \'doubting Thomas\' deyimi hangi anlatıdan gelir?', 'Havari Tomas\'ın dirilen İsa\'yı görmeden inanmayacağını söylemesi', ['Tomas\'ın tutuklanan İsa\'yı aynı gece üç kez inkâr etmesi', 'Tomas\'ın vergi memurluğundan ayrılması', 'Tomas\'ın Hindistan\'a gitmeyi reddetmesi'], 'Yuhanna İncili\'ne göre Tomas, İsa\'nın yaralarını görüp dokunmadıkça dirildiğine inanmayacağını söylemiştir.'),
  ('Hristiyan öğretisinde Tanrı\'nın Oğlu\'nun İsa\'da insan bedenine bürünmesini anlatan terim hangisidir?', 'Enkarnasyon (bedenleşme)', ['Rezürreksiyon (diriliş)', 'Transubstantiasyon', 'Asensiyon (göğe yükseliş)'], 'Enkarnasyon, Latince \'bedene girme\' anlamına gelir ve Tanrı\'nın Oğlu\'nun insan olarak doğduğu inancını anlatır.'),
  ('451\'de toplanan ve İsa\'nın tek kişilikte hem tam tanrısal hem tam insani iki doğası olduğunu ilan eden konsil hangi şehirde yapılmıştır?', 'Kadıköy', ['Efes', 'İstanbul', 'Trento'], 'Kalkedon Konsili iki doğa öğretisini ilan etmiş; bunu kabul etmeyen Kıpti, Ermeni ve Süryani kiliseleri ayrı bir yol izlemiştir.'),
  ('431\'de toplanan ve Meryem\'in \'Tanrı doğuran\' (Theotokos) olarak anılmasını onaylayıp Nestorius\'u mahkûm eden konsil hangi şehirde yapılmıştır?', 'Efes', ['İznik', 'Kadıköy', 'Antakya'], 'Efes Konsili, Meryem için Theotokos unvanını reddeden İstanbul Patriği Nestorius\'un görüşlerini mahkûm etmiştir.'),
  ('1962-1965 yılları arasında toplanan ve Katolik ayinlerinde yerel dillerin kullanılmasının önünü açan konsil hangisidir?', 'II. Vatikan Konsili', ['Trento Konsili', 'V. Lateran Konsili', 'I. Vatikan Konsili'], 'II. Vatikan Konsili, ayinlerde Latince yerine yerel dillerin kullanılmasına izin vermiş ve diğer dinlerle diyalog konusunda yeni bir tutum benimsemiştir.'),
  ('380 Selanik Fermanı ile Hristiyanlığı Roma İmparatorluğu\'nun resmî dini yapan imparator kimdir?', 'I. Theodosius', ['I. Konstantin', 'Jülyen', 'I. Justinianus'], 'I. Theodosius 380\'de İznik inancını izleyen Hristiyanlığı devletin resmî dini ilan etmiştir.'),
  ('Ortodoks kiliselerin yönetim yapısını Katolik Kilisesi\'nden ayıran temel özellik hangisidir?', 'Bağımsız (otosefal) kiliselerden oluşması', ['Tek bir merkezden yönetilip tek bir başkana bağlı olması', 'Din adamlarının hiçbir koşulda evlenememesi', 'Ayinlerin yalnız Latince yapılması'], 'Ortodoks dünyası Rus, Sırp, Yunan, Rumen gibi otosefal kiliselerden oluşur; Katolik Kilisesi ise papaya bağlı merkezî bir yapıdır.'),
  ('Yunanistan\'da yalnız erkek keşişlerin yaşadığı, 20 manastırdan oluşan özerk Ortodoks keşiş cumhuriyeti hangi dağdadır?', 'Aynaroz (Athos) Dağı', ['Olimpos Dağı', 'Sina Dağı', 'Parnassos Dağı'], 'Aynaroz Dağı, Bizans döneminden beri Ortodoks keşişliğin merkezidir; geleneksel olarak kadınların girişine izin verilmez.'),
  ('Luther\'in öğretisinin özünü oluşturan \'sola fide\' ilkesi ne anlama gelir?', 'İnsanın yalnız iman yoluyla kurtuluşa erdiği', ['Yalnız rahiplerin Kutsal Kitap\'ı yorumlayabileceği', 'Kurtuluşun yalnız iyi işlerle kazanıldığı', 'Papanın yanılmaz olduğu'], '\'Sola fide\' (yalnız imanla) ilkesi, kurtuluşun iyi işlerle ya da kilise aracılığıyla değil, Tanrı\'nın lütfuna iman yoluyla olduğunu savunur.'),
  ('Protestan Reformu\'nun \'sola scriptura\' ilkesi aşağıdaki tutumlardan hangisine yol açmıştır?', 'Kutsal Kitap\'ın halkın konuştuğu dillere çevrilmesine', ['Ayinlerin yalnız Latince yapılmasına', 'Kilise geleneğinin ve papa kararlarının Kutsal Kitap\'tan üstün tutulmasına', 'Papanın kararlarının tartışmasız kabul edilmesine'], '\'Yalnız Kutsal Kitap\' ilkesi inancın tek kaynağını Kutsal Kitap sayar; bu da herkesin okuyabilmesi için yerel dillere çeviriyi teşvik etmiştir. Luther de Kutsal Kitap\'ı Almancaya çevirmiştir.'),
  ('İngiltere Kilisesi\'nin (Anglikan Kilisesi) Roma\'dan ayrılmasının doğrudan nedeni hangisidir?', 'Papanın VIII. Henry\'nin evliliğini iptal etmeyi reddetmesi', ['İngiliz halkının Luther\'in öğretisini parlamentoda yapılan oylamayla benimsemesi', 'Kutsal Kitap\'ın İngilizceye çevrilmesinin yasaklanması', 'İngiltere\'nin Haçlı Seferleri\'ne katılmayı reddetmesi'], 'VIII. Henry, Aragonlu Katherine ile evliliğinin iptalini papadan alamayınca 1534 Üstünlük Yasası ile kendini İngiltere Kilisesi\'nin başı ilan etmiştir.'),
  ('İsviçre\'de Zürih merkezli Reform hareketine öncülük eden din adamı kimdir?', 'Ulrich Zwingli', ['Jan Hus', 'John Wycliffe', 'Ignatius Loyola'], 'Ulrich Zwingli 1520\'lerde Zürih\'te Reform\'u başlatmıştır; Luther\'le özellikle Komünyon konusunda anlaşamamıştır.'),
  ('Luther\'den yaklaşık bir asır önce kilise yozlaşmasını eleştirdiği için 1415\'te Konstanz\'da yakılan Çek reformcu kimdir?', 'Jan Hus', ['Jean Calvin', 'Thomas Müntzer', 'Philipp Melanchthon'], 'Prag\'lı Jan Hus, John Wycliffe\'ten etkilenerek kiliseyi eleştirmiş ve Konstanz Konsili kararıyla yakılmıştır.'),
  ('Yalnız inancını bilinçli olarak açıklayan yetişkinlerin vaftiz edilmesi gerektiğini savunan Protestan topluluklara ne ad verilir?', 'Anabaptistler', ['Anglikanlar', 'Lutherciler', 'Kalvinistler'], 'Anabaptistler bebek vaftizini reddetmiş, inancını ilan eden yetişkinlerin vaftizini savunmuştur; Baptist kiliseler de bu ilkeyi benimser.'),
  ('18. yüzyılda John Wesley\'in İngiltere\'de başlattığı, düzenli ve disiplinli dinî yaşamı vurgulayan Protestan hareketi hangisidir?', 'Metodizm', ['Kuakerlik', 'Presbiteryenlik', 'Lutheranizm'], 'Metodizm, John ve Charles Wesley\'in Oxford\'daki \'yöntemli\' dinî çalışmalarından adını almıştır.'),
  ('Katolik Kilisesi\'nin Reform\'a karşı başlattığı yenilenme hareketi içinde 1540\'ta kurulan, eğitim ve misyonerlikle öne çıkan tarikat hangisidir?', 'Cizvitler', ['Benediktenler', 'Kartuziyenler', 'Sistersiyenler'], 'Ignatius Loyola\'nın kurduğu İsa Cemiyeti (Cizvitler), okulları ve Asya ile Amerika\'daki misyonerlik faaliyetleriyle Karşı Reform\'un öncülerinden olmuştur.'),
  ('Protestan Reformu\'nun yayılmasında matbaanın rolünü en iyi açıklayan ifade hangisidir?', 'Broşür ve çevirilerin hızla çoğaltılıp geniş kitlelere ulaşmasını sağlamıştır', ['Kilisenin tüm kitapları yakmasına yol açmıştır', 'Reformcuların yalnız el yazmalarıyla ve gizlice iletişim kurmasını zorunlu kılmıştır', 'Latincenin halk arasında yaygınlaşmasını sağlamıştır'], 'Luther\'in yazıları ve Almanca Kutsal Kitap matbaa sayesinde binlerce kopya basılmış, fikirler kısa sürede Avrupa\'ya yayılmıştır.'),
  ('Katolik Kilisesi\'nde kabul edilen sakramentlerin sayısı kaçtır?', 'Yedi', ['İki', 'Beş', 'On iki'], 'Katoliklikte vaftiz, konfirmasyon, Efkaristiya, tövbe, hasta yağlama, rahiplik ve evlilik olmak üzere yedi sakrament vardır; çoğu Protestan kilise yalnız vaftiz ve Komünyonu kabul eder.'),
  ('Katolik öğretide ayin sırasında kutsanan ekmek ve şarabın özünün İsa\'nın bedeni ve kanına dönüştüğü inancı hangi terimle anlatılır?', 'Transubstantiasyon', ['Enkarnasyon', 'Predestinasyon', 'Kanonizasyon'], '1215 IV. Lateran Konsili\'nde tanımlanan transubstantiasyon öğretisi, görünüşün aynı kalırken ekmek ve şarabın özünün değiştiğini savunur.'),
  ('Ölümünden yıllar sonra bir rahibenin yaşamı incelenip ona atfedilen mucizeler araştırılıyor ve sonunda papa onu resmî olarak aziz ilan ediyor. Bu sürece ne ad verilir?', 'Kanonizasyon', ['Beatifikasyon öncesi aforoz', 'Konsekrasyon', 'Ekskomünikasyon'], 'Kanonizasyon, kişinin aziz ilan edilmesidir; öncesinde genellikle \'kutsanmış\' anlamında beatifikasyon aşaması gelir.'),
  ('6. yüzyılda İtalya\'da yazdığı kuralla \'dua et ve çalış\' (ora et labora) ilkesini Batı manastır yaşamının temeli yapan kişi kimdir?', 'Nursialı Benedictus', ['Assisili Francesco', 'Ignatius Loyola', 'Dominicus'], 'Benedictus\'un Monte Cassino\'da yazdığı Benedikten Kuralı, Batı manastırlarında dua, çalışma ve okumayı dengeleyen yaşamın temeli olmuştur.'),
  ('\'İtiraflar\' adlı otobiyografik eseri ve \'Tanrı Devleti\' kitabıyla Batı Hristiyan düşüncesini derinden etkileyen Kuzey Afrikalı piskopos kimdir?', 'Hippolu Augustinus', ['Thomas Aquinas', 'Origenes', 'Tertullianus'], 'Augustinus (354-430), bugünkü Cezayir\'deki Hippo\'nun piskoposuydu; \'İtiraflar\' ve \'Tanrı Devleti\' Batı düşüncesinin temel eserlerindendir.'),
  ('Lübnan\'da yaygın olan, Doğu ayinini sürdürmekle birlikte Roma\'daki papaya bağlı olan Hristiyan topluluk hangisidir?', 'Maruniler', ['Kıptiler', 'Süryani Ortodokslar', 'Ermeni Apostolikler'], 'Maruni Kilisesi, adını Aziz Maron\'dan alır; Süryani ayin geleneğini sürdürür ancak Katolik Kilisesi ile tam birlik içindedir.'),
  ('Bizans\'ta 8-9. yüzyıllarda kutsal tasvirlerin kullanılıp kullanılmaması üzerine yaşanan çatışma hangi adla bilinir?', 'İkonoklazma (tasvir kırıcılık)', ['Filioque tartışması', 'Arius tartışması', 'Hesykhazm (sessizlik duası)'], 'İkonoklazma döneminde ikonaların kullanımı yasaklanmış, 843\'te ikonaların kullanımı yeniden kabul edilmiştir; Ortodokslar bunu \'Ortodoksluğun Zaferi\' olarak anar.'),
  ('Bir Rus Ortodoks kilisesine giren ziyaretçi, sunak bölümünü cemaatten ayıran, üzerinde sıra sıra ikonalar bulunan ve ortasında \'Kral Kapısı\' olan bir duvarla karşılaşıyor. Bu bölmeye ne ad verilir?', 'İkonostasis', ['Apsis', 'Nartheks', 'Transept'], 'İkonostasis, ikonalarla kaplı bir duvar ya da bölmedir; ortadaki \'Kral Kapısı\' ayin sırasında açılıp kapanır.'),
  ('Bir kilisede girişle ana mekân arasında bulunan, eskiden vaftiz edilmemiş kişilerin beklediği giriş holüne ne ad verilir?', 'Nartheks', ['Apsis', 'Kripta', 'Kubbe kasnağı'], 'Nartheks, kilisenin batı girişindeki dar holdür; erken dönemde vaftiz adaylarının ayini buradan izlediği bilinir.'),
  ('Bir mimarlık öğrencisi, haç planlı bir katedralin planını çizerken uzun ana gövdeyi sunağa yakın bir noktada dik açıyla kesen enine kolları işaretliyor. Bu enine kollara ne ad verilir?', 'Transept', ['Nef', 'Apsis', 'Çan kulesi'], 'Transept, nefi dik keserek kiliseye haç biçimi veren enine bölümdür.'),
  ('Bir katedrali gezen turistler, sunağın altındaki merdivenlerden inerek azizlerin mezarlarının bulunduğu tonozlu bir yeraltı odasına giriyor. Bu bölümün adı nedir?', 'Kripta', ['Nartheks', 'Transept', 'Ambon'], 'Kripta, kilisenin altında bulunan tonozlu mezar ya da kalıntı odasıdır.'),
  ('Roma döneminde mahkeme ve pazar binası olarak kullanılan, sonra Hristiyanların kilise planı olarak benimsediği uzun dikdörtgen yapı türü hangisidir?', 'Bazilika', ['Rotunda', 'Forum', 'Amfitiyatro'], 'Bazilika Roma\'da kamu yapısıydı; Hristiyanlık serbest kalınca geniş cemaati alabilen bu plan kiliselere uyarlanmıştır.'),
  ('Kelime sayısı bakımından Kur\'an\'ın en kısa suresi hangisidir?', 'Kevser', ['Fatiha', 'Bakara', 'İhlas'], 'Kevser suresi üç ayet ve en az kelimeyle Kur\'an\'ın en kısa suresidir; İhlas dört, Fatiha yedi ayetten oluşur.'),
  ('Kur\'an\'ın iki kapak arasında bir kitap hâlinde toplanmış nüshasına ne ad verilir?', 'Mushaf', ['Hadis', 'Siyer', 'Cüz'], 'Mushaf, sayfaları bir araya getirilmiş Kur\'an nüshasıdır; ilk derleme Hz. Ebubekir döneminde yapılmıştır.'),
  ('Kur\'an\'ın standart bir mushaf hâlinde çoğaltılıp çeşitli bölgelere gönderilmesi hangi halife döneminde gerçekleşmiştir?', 'Hz. Osman', ['Hz. Ebubekir', 'Hz. Ömer', 'Hz. Ali'], 'Hz. Ebubekir döneminde toplanan metin, Hz. Osman döneminde çoğaltılarak Kûfe, Basra ve Şam gibi merkezlere gönderilmiştir.'),
  ('Sünni dünyada en güvenilir hadis derlemeleri arasında ilk sırada sayılan iki eser hangisidir?', 'Buhari ve Müslim\'in Sahih\'leri', ['Taberi ve İbn Kesir\'in tefsirleri', 'Gazali ve Farabi\'nin eserleri', 'İbn Haldun ve Mesudi\'nin tarih kitapları'], 'Buhari\'nin \'el-Câmiu\'s-Sahîh\'i ile Müslim\'in \'Sahîh\'i, Sünni gelenekte Kütüb-i Sitte\'nin en güvenilir iki eseri kabul edilir.'),
  ('Bir hadisi aktaranların kesintisiz olarak sıralandığı ravi zincirine ne ad verilir?', 'İsnad (sened)', ['Metin', 'Kıraat (okuma biçimi)', 'Mushaf'], 'Hadis biliminde isnad, rivayeti Hz. Muhammed\'e kadar ulaştıran raviler zinciridir; hadisin söz kısmına ise metin denir.'),
  ('İslam inancında altı temel iman esası arasında aşağıdakilerden hangisi yer almaz?', 'Hacca gitmek', ['Meleklere inanmak', 'Ahiret gününe inanmak', 'Kitaplara inanmak'], 'İmanın şartları Allah\'a, meleklere, kitaplara, peygamberlere, ahirete ve kadere inanmaktır; hac ise İslam\'ın şartlarından, yani ibadetlerdendir.'),
  ('Namaza çağrı olarak minareden okunan ezandan farklı olarak, farz namaz kılınmaya başlamadan hemen önce okunan çağrıya ne ad verilir?', 'Kamet', ['Salâ', 'Tekbir', 'Hutbe'], 'Kamet, cemaatle namaza durmadan hemen önce okunur; ezana benzer sözler içerir ve \'namaz başladı\' anlamında bir ifade eklenir.'),
  ('Bir camide namaz sırasında müezzinlerin cemaatin üstünde, direklerle taşınan yükseltilmiş bir platformda durup tekbirleri yüksek sesle tekrar ettiği görülüyor. Bu bölüme ne ad verilir?', 'Müezzin mahfili', ['Minber', 'Şadırvan', 'Son cemaat yeri'], 'Müezzin mahfili, cami içinde müezzinlerin ibadet sırasında bulunduğu yükseltilmiş platformdur.'),
  ('Camiye geç gelenlerin namaz kıldığı, ana mekânın önündeki revaklı bölüme ne ad verilir?', 'Son cemaat yeri', ['Mihrap', 'Hünkâr mahfili', 'Hazire'], 'Son cemaat yeri, caminin girişindeki revaklı bölümdür; adı cemaate geç kalanların burada namaz kılmasından gelir.'),
  ('Büyük Osmanlı camilerinde padişahın ve maiyetinin namaz kılması için ayrılmış, kafesli ve yükseltilmiş bölüme ne ad verilir?', 'Hünkâr mahfili', ['Müezzin mahfili', 'Kümbet', 'Son cemaat yeri'], 'Hünkâr mahfili, selatin camilerinde padişahın güvenlik içinde ve ayrı olarak namaz kılması için yapılmış bölümdür.'),
  ('Bir selatin camisinin arka bahçesinde, duvarla çevrili bir alanda caminin banisi olan paşa ile ailesinin mezar taşları bulunuyor. Bu küçük mezarlığa ne ad verilir?', 'Hazire', ['Türbe', 'Sebil', 'Şadırvan'], 'Hazire, camilerin avlusunda ya da arkasında yer alan, çevresi duvarla çevrili küçük mezarlıktır; türbe ise üstü örtülü anıt mezardır.'),
  ('Haccın en temel rüknü sayılan ve Zilhicce\'nin 9. günü belirli bir alanda bulunmayı gerektiren uygulama hangisidir?', 'Arafat vakfesi', ['Kâbe tavafı', 'Şeytan taşlama', 'Mina\'da kurban kesme ve tıraş olma'], 'Arafat\'ta vakfe haccın olmazsa olmaz rüknüdür; bu günü kaçıran kişinin haccı geçerli olmaz.'),
  ('Hac sırasında Mina\'da belli taş sütunlara küçük taşlar atılmasına ne ad verilir?', 'Şeytan taşlama (remy)', ['Tavaf-ı ziyaret (farz tavaf)', 'Sa\'y', 'Müzdelife vakfesi'], 'Remy, Hz. İbrahim\'in şeytanı taşlamasını anan uygulamadır; hacılar Cemerat denilen sütunlara taş atar.'),
  ('Hac ile umre arasındaki temel fark hangisidir?', 'Hac belli günlerde yapılır ve Arafat vakfesini içerir, umre yılın çoğu zamanında yapılabilir', ['Umre yalnız Medine\'de, hac yalnız Mekke\'de yapılır', 'Hac için ihrama girilmez, umre için girilir', 'Umre yalnız Ramazan\'da yapılabilir, hac ise her ay yapılabilir'], 'Hac Zilhicce ayının belli günlerinde yapılır ve Arafat vakfesini içerir; umrede vakfe yoktur ve yılın çoğu zamanında yapılabilir.'),
  ('Kâbe\'nin doğu köşesine yerleştirilmiş olan ve tavafın başlangıç noktasını belirleyen taş hangisidir?', 'Hacerü\'l-Esved', ['Makam-ı İbrahim', 'Hatim', 'Mizab-ı Rahmet'], 'Hacerü\'l-Esved (Kara Taş), Kâbe\'nin doğu köşesindeki taştır; tavaf bu köşeden başlar ve burada biter.'),
  ('Kâbe\'yi örten, üzerinde altın ve gümüş iple işlenmiş yazılar bulunan siyah örtüye ne ad verilir?', 'Kisve', ['Seccade-i Şerif', 'Sancak-ı Şerif', 'Hırka-i Şerif'], 'Kâbe\'nin örtüsüne kisve denir; her yıl yenilenir ve Osmanlı döneminde Mısır\'da dokunup Surre Alayı\'yla gönderilirdi.'),
  ('Hz. Ali ile Muaviye arasındaki Sıffin Savaşı\'nın ardından hakem olayını kabul etmeyip Ali\'nin saflarından ayrılan grup hangisidir?', 'Hariciler', ['Mutezile', 'Mürcie', 'Cebriye'], 'Hariciler (\'ayrılanlar\'), hakem olayını kabul ettiği için Hz. Ali\'den ayrılmış ve büyük günah işleyenin imandan çıktığını savunmuştur.'),
  ('İslam\'da ilk mescit olarak kabul edilen ve hicret sırasında Medine yakınında yapılan mescit hangisidir?', 'Kuba Mescidi', ['Mescid-i Nebevi', 'Mescid-i Aksa', 'Mescid-i Haram'], 'Kuba Mescidi, Hz. Muhammed\'in hicret sırasında Medine\'ye girmeden önce yaptırdığı, İslam\'ın ilk mescidi kabul edilen yapıdır.'),
  ('Türkiye\'nin doğu ve güneydoğusundaki bazı Müslümanlar arasında yaygın olan fıkıh mezhebi hangisidir?', 'Şafii', ['Maliki', 'Hanbeli', 'Caferi'], 'Türkiye\'de Hanefiliğin yanı sıra özellikle Doğu ve Güneydoğu Anadolu\'da Şafii mezhebi yaygındır.'),
  ('Kuzey Afrika ve Batı Afrika\'da en yaygın fıkıh mezhebi hangisidir?', 'Maliki', ['Hanefi', 'Hanbeli', 'Zeydi'], 'Medineli İmam Malik\'e dayanan Maliki mezhebi Fas, Cezayir, Tunus, Libya ve Batı Afrika\'da yaygındır.'),
  ('Semerkantlı âlim Ebu Mansur el-Maturidi\'nin adını taşıyan ve Türk dünyasında yaygın olan mezhep hangi alanla ilgilidir?', 'İnanç (itikat) esasları', ['İbadetlerin uygulanışı', 'Kur\'an\'ın okunuş biçimi', 'Miras paylaşımı'], 'Maturidilik itikadi (inanç) mezheptir; Hanefi fıkhını izleyen Türkler arasında inanç alanında yaygınlaşmıştır.'),
  ('Ebu\'l-Hasen el-Eş\'ari\'nin adını taşıyan itikadi mezhep hangisidir?', 'Eş\'arilik', ['Maturidilik', 'Mutezile', 'Haricilik'], 'Eş\'arilik, 10. yüzyılda Mutezile\'den ayrılan el-Eş\'ari\'nin görüşlerine dayanan Sünni itikadi mezheptir; özellikle Şafii ve Maliki çevrelerde yaygınlaşmıştır.'),
  ('Aklı ön plana çıkaran, Kur\'an\'ın yaratılmış olduğunu savunan ve Abbasi halifesi Me\'mun döneminde resmî destek gören kelam ekolü hangisidir?', 'Mutezile', ['Eş\'arilik', 'Haricilik', 'Selefilik'], 'Mutezile akla geniş yer tanıyan bir kelam okuludur; Me\'mun döneminde \'Mihne\' denilen sorgulama süreciyle görüşleri resmî tutum hâline getirilmiştir.'),
  ('Şiilikte en yaygın kol olan ve İran\'ın resmî mezhebi olan anlayış, kaç imamı kabul etmesiyle adlandırılır?', 'On iki', ['Yedi', 'Beş', 'Dört'], 'İsna Aşeriyye (On İki İmamcılık), Hz. Ali\'den başlayarak on iki imamı kabul eder; fıkıhta Caferi mezhebini izler.'),
  ('Şii fıkhında izlenen ve adını altıncı imamdan alan mezhep hangisidir?', 'Caferi', ['Zeydi', 'Hanefi', 'İsmaili'], 'Caferi mezhebi, Hz. Ali soyundan altıncı imam Cafer es-Sadık\'a dayanır.'),
  ('Yedinci imam olarak İsmail bin Cafer\'i kabul eden ve bugün bir kolu Ağa Han\'ı imam tanıyan Şii topluluk hangisidir?', 'İsmaililer', ['Zeydiler', 'Caferiler', 'Nusayriler'], 'İsmaililer, imamlığın Cafer es-Sadık\'ın oğlu İsmail\'in soyundan devam ettiğine inanır; Nizari İsmaililer Ağa Han\'ı imamları olarak kabul eder.'),
  ('Sünni ve Şii ayrımının tarihsel kökeni en çok hangi konudaki anlaşmazlığa dayanır?', 'Hz. Muhammed\'den sonra topluluğun liderinin kim olması gerektiği', ['Namazın günde kaç vakit kılınacağı', 'Kur\'an\'ın hangi dilde okunacağı', 'Hac ibadetinin hangi ayda yapılacağı'], 'Şiiler liderliğin (imamet) Hz. Ali ve soyuna ait olduğunu savunmuş; Sünniler ise seçilen ilk halifelerin meşruiyetini kabul etmiştir.'),
  ('Mevlânâ\'nın düşünce dünyasını derinden etkileyen ve Konya\'da tanıştığı gezgin derviş kimdir?', 'Şems-i Tebrizi', ['Sadreddin Konevi', 'Yunus Emre', 'Muhyiddin İbnü\'l-Arabi'], 'Mevlânâ\'nın 1244\'te Konya\'da Şems-i Tebrizi ile karşılaşması onun hayatında dönüm noktası olmuş, şiirlerinin büyük bölümü bu etkiyle yazılmıştır.'),
  ('Sessiz (hafi) zikri benimseyen, Bahaeddin Nakşibend\'e nispet edilen ve Osmanlı\'da yaygınlaşan tarikat hangisidir?', 'Nakşibendilik', ['Rifailik', 'Kadirilik', 'Mevlevilik'], 'Nakşibendilik 14. yüzyılda Buhara\'da Bahaeddin Nakşibend\'in adıyla anılmış, sessiz zikir ve şeriata bağlılığı öne çıkarmıştır.'),
  ('Bağdat\'ta yaşamış Abdülkadir Geylani\'ye nispet edilen tarikat hangisidir?', 'Kadirilik', ['Nakşibendilik', 'Halvetilik', 'Bayramilik'], 'Kadirilik, 12. yüzyılda Bağdat\'ta yaşamış Abdülkadir Geylani\'ye dayanır ve İslam dünyasının en yaygın tarikatlarındandır.'),
  ('Ankara\'da yaşamış Hacı Bayram-ı Veli\'nin kurduğu tarikat hangisidir?', 'Bayramilik', ['Bektaşilik', 'Mevlevilik', 'Kadirilik'], 'Hacı Bayram-ı Veli 15. yüzyılda Ankara\'da Bayramiliği kurmuştur; Akşemseddin onun öğrencilerindendir.'),
  ('16. yüzyılda yaşamış, Alevi edebiyatında deyişleri ve Hızır Paşa\'ya karşı tutumuyla bilinen ozan kimdir?', 'Pir Sultan Abdal', ['Karacaoğlan', 'Âşık Veysel', 'Dadaloğlu'], 'Sivaslı Pir Sultan Abdal, Alevi-Bektaşi şiirinin en önemli adlarındandır; halk anlatılarına göre Hızır Paşa tarafından astırılmıştır.'),
  ('Ahmed Yesevi\'nin türbesi bugün hangi ülkededir?', 'Kazakistan', ['Özbekistan', 'Türkmenistan', 'Kırgızistan'], 'Ahmed Yesevi Türbesi, Kazakistan\'ın Türkistan şehrindedir; Timur döneminde yaptırılmış ve UNESCO Dünya Mirası listesine alınmıştır.'),
  ('Kuzey Irak\'taki Laleş vadisini en kutsal mekânları sayan inanç topluluğu hangisidir?', 'Ezidiler', ['Dürziler', 'Bahailer', 'Mandeiler'], 'Laleş, Ezidilerin en kutsal mekânıdır; Şeyh Adi\'nin türbesi buradadır ve Ezidiler ömürlerinde en az bir kez buraya gitmeye çalışır.'),
  ('Hatay ve Adana yöresinde yaşayan, Arapça konuşan ve tarihsel olarak Nusayri adıyla da anılan topluluğa bugün daha çok hangi ad verilir?', 'Arap Alevileri', ['Dürziler', 'Süryani Katolikler', 'Ezidiler'], 'Nusayrilik adını 9. yüzyıldaki Muhammed bin Nusayr\'dan alır; Türkiye\'deki mensupları kendilerini çoğunlukla Arap Alevisi olarak tanımlar.'),
  ('Zerdüştlüğün kutsal metinlerinin toplandığı külliyatın adı nedir?', 'Avesta', ['Vedalar', 'Tripitaka', 'Zend-i Şerif'], 'Avesta, Zerdüştlüğün kutsal metinler derlemesidir; içindeki Gathalar\'ın Zerdüşt\'ün kendisine ait ilahiler olduğu kabul edilir.'),
  ('Zerdüşt tapınaklarında sürekli yanık tutulan unsur nedir ve neyi simgeler?', 'Ateş; Ahura Mazda\'nın saflığını ve ışığını', ['Su; dünyanın yaratılışını', 'Toprak; ataların ruhlarını', 'Rüzgâr; kötü ruhların gücünü ve kışın sertliğini'], 'Zerdüştlükte ateş tanrının saflığını ve hakikati simgeler; ateş tapınaklarında (ateşkede) kutsal ateş söndürülmeden tutulur. Zerdüştler ateşe tapmaz, onu simge kabul eder.'),
  ('Geleneksel Zerdüştlükte ölülerin bedenlerinin toprağı ve ateşi kirletmemesi için açık havada bırakıldığı yapılara ne ad verilir?', 'Sessizlik kuleleri', ['Ateş tapınakları', 'Stupalar', 'Zigguratlar'], 'Ölü bedeni kirli sayıldığından toprağa gömülmez ya da yakılmaz; geleneksel olarak \'dakhma\' denen sessizlik kulelerinde akbabalara bırakılırdı.'),
  ('Zerdüştlüğün simgesi olarak bilinen, kanatlı bir insan figüründen oluşan sembol hangisidir?', 'Faravahar', ['Ankh', 'Khanda', 'Om'], 'Faravahar, Pers kabartmalarında görülen kanatlı figürdür ve bugün Zerdüştlüğün en tanınmış simgesidir.'),
  ('3. yüzyılda İran\'da ortaya çıkan, Zerdüştlük, Hristiyanlık ve Budizm\'den unsurlar birleştiren ve ışık ile karanlığın mücadelesini öğreten din hangisidir?', 'Maniheizm', ['Mitraizm', 'Mazdekizm', 'Gnostisizm'], 'Mani\'nin kurduğu Maniheizm, ışık ve karanlık arasındaki kozmik mücadeleyi merkez alan bir düalist dindir.'),
  ('1945\'te Mısır\'da bulunan ve Tomas İncili dahil birçok Gnostik metni içeren el yazmaları koleksiyonu hangi adla bilinir?', 'Nag Hammadi kitaplığı', ['Ölü Deniz Yazmaları', 'Codex Sinaiticus', 'Kahire Genizası belgeleri'], 'Nag Hammadi yakınlarında bir çiftçinin bulduğu Kıptice yazılı kodeksler, erken Hristiyan dönemine ait Gnostik metinleri içerir.'),
  ('1947\'de Kumran yakınındaki mağaralarda bulunan ve İbranice Kutsal Kitap\'ın bilinen en eski nüshalarından bazılarını içeren yazmalar hangileridir?', 'Ölü Deniz Yazmaları', ['Nag Hammadi metinleri', 'Kahire Genizası belgeleri', 'Codex Vaticanus'], 'Ölü Deniz Yazmaları MÖ 3. yüzyıl ile MS 1. yüzyıl arasına tarihlenir; bir Bedevi çobanın Kumran mağaralarında bulmasıyla ortaya çıkmıştır.'),
  ('İbranice Kutsal Kitap\'ın MÖ 3. yüzyılda İskenderiye\'de yapıldığı kabul edilen Yunanca çevirisine ne ad verilir?', 'Septuaginta', ['Vulgata', 'Peşitta', 'Targum'], 'Septuaginta adını, geleneğe göre çeviriyi yapan 72 bilginden alır; erken Hristiyanların kullandığı Eski Ahit bu çeviriydi.'),
  ('4. yüzyılın sonunda Aziz Hieronymus\'un yaptığı ve Katolik Kilisesi\'nde yüzyıllarca resmî metin olarak kullanılan Latince Kutsal Kitap çevirisi hangisidir?', 'Vulgata', ['Septuaginta', 'Peşitta', 'King James çevirisi'], 'Hieronymus\'un (Jerome) Latince çevirisi Vulgata, \'halka açık\' anlamına gelir; Trento Konsili onu Katolik Kilisesi\'nin resmî metni ilan etmiştir.'),
  ('1611\'de İngiltere\'de yayımlanan ve İngiliz dili ile edebiyatını derinden etkileyen Kutsal Kitap çevirisi hangi kralın adıyla anılır?', 'I. James', ['VIII. Henry', 'I. Charles', 'III. William'], 'King James Version (Yetkili Çeviri), I. James\'in desteğiyle hazırlanmış ve İngilizcenin en etkili metinlerinden biri olmuştur.'),
  ('Bhagavad Gita\'da Arjuna\'ya savaşçı olarak kendi görevini yerine getirmesi, başkasının görevini iyi yapmaktan daha üstün olduğu öğütleniyor. Bu öğüt Hinduizmin hangi kavramıyla ilgilidir?', 'Dharma', ['Karma', 'Mokşa', 'Maya'], 'Dharma hem evrensel düzeni hem de bireyin konumuna göre yerine getirmesi gereken ahlaki ve toplumsal ödevi anlatır.'),
  ('Hinduizmde Vişnu\'nun dünyaya inerek aldığı biçimlere verilen ad hangisidir ve bunlara örnek olarak kimler gösterilir?', 'Avatar; Rama ve Krişna', ['Guru; Nanak ve Arjuna', 'Bodhisattva; Avalokiteşvara ve Manjuşri', 'Rişi; Vyasa ve Valmiki'], 'Avatar \'iniş\' demektir; Vişnu\'nun on avatarı arasında Rama ve Krişna en çok sevilenlerdir.'),
  ('Klasik Hindu toplum düzeninde dört varna (sınıf) hangileridir?', 'Brahmin, Kşatriya, Vaişya, Şudra', ['Brahmin, Lama, Guru, Sadhu', 'Kşatriya, Samuray, Şudra, Dalit', 'Brahmin, Mobed, Rişi, Vaişya'], 'Varna sisteminde Brahminler din adamı ve bilginleri, Kşatriyalar savaşçı ve yöneticileri, Vaişyalar tüccar ve çiftçileri, Şudralar ise hizmet edenleri kapsar.'),
  ('Hinduizmde ölülerin geleneksel olarak yakılmasıyla ilgili hangi açıklama doğrudur?', 'Ruhun bedenden ayrılıp yolculuğuna geçişini kolaylaştırdığına inanılır', ['Ölülerin yeniden dirilişi için bedenin bozulmadan korunması amaçlanır', 'Bedenin akbabalara bırakılması gerektiğine inanılır', 'Yalnız din adamları yakılır, diğerleri gömülür'], 'Hindu geleneğinde yakma (antyeşti), ruhun beden bağından kurtulup yolculuğuna devam etmesini sağlayan bir ritüel olarak görülür; küller çoğu zaman kutsal nehirlere bırakılır.'),
  ('Tibetli keşişler günlerce renkli kum tanecikleriyle iç içe daireler ve karelerden oluşan simgesel bir evren çiziyor, tören bitince de kumu süpürüp suya döküyor. Yapılan bu kutsal diyagram nedir?', 'Mandala', ['Mantra', 'Mudra', 'Stupa'], 'Mandala Sanskritçede \'daire\' demektir; Tibet Budist keşişlerinin renkli kumla yapıp tören sonunda bozdukları mandalalar ünlüdür.'),
  ('Bir müzede sağ eli avuç içi dışa dönük ve yukarı kalkık, sol eli kucağında duran bir Buda heykeli sergileniyor; rehber bu el duruşunun \'korkma\' anlamına geldiğini söylüyor. Bu tür simgesel el duruşlarına ne ad verilir?', 'Mudra', ['Mantra', 'Mandala', 'Asana'], 'Mudralar, korkusuzluk, öğretme ya da meditasyon gibi anlamları simgeleyen el hareketleridir; heykellerde sıkça görülür.'),
  ('Budizmin kurucusu Siddhartha Gautama\'nın doğduğu kabul edilen Lumbini bugün hangi ülkededir?', 'Nepal', ['Hindistan', 'Sri Lanka', 'Tibet'], 'Lumbini, Nepal\'in güneyinde, Hindistan sınırına yakındır ve UNESCO Dünya Mirası listesindedir.'),
  ('Geleneğe göre prens Siddhartha\'nın saraydan ayrılıp hakikati aramaya karar vermesine yol açan \'dört görüntü\' hangileridir?', 'Yaşlı bir adam, bir hasta, bir ölü ve bir keşiş', ['Bir kral, bir asker, bir tüccar ve zincirli bir köle', 'Bir aslan, bir fil, bir at ve bir yılan', 'Bir tapınak, bir saray, bir nehir ve bir dağ'], 'Anlatıya göre Siddhartha yaşlılık, hastalık ve ölümle karşılaşınca acının evrenselliğini fark etmiş, huzurlu bir keşiş görünce de arayışa çıkmıştır.'),
  ('Buda\'nın aydınlandıktan sonra ilk vaazını verdiği Geyik Parkı hangi yerdedir?', 'Sarnath', ['Bodh Gaya', 'Lumbini', 'Kuşinagar'], 'Buda ilk vaazını Varanasi yakınındaki Sarnath\'ta beş eski arkadaşına vermiştir; bu olay \'Dharma çarkının döndürülmesi\' olarak anılır.'),
  ('Aşağıdakilerden hangisi Budizmdeki Sekiz Dilimli Yol\'un basamaklarından biri değildir?', 'Doğru kurban', ['Doğru görüş', 'Doğru söz', 'Doğru dikkat'], 'Sekiz dilimli yol doğru görüş, niyet, söz, eylem, geçim, çaba, farkındalık ve konsantrasyondan oluşur; kurban ritüeli bu yolda yer almaz.'),
  ('Güneydoğu Asya\'da (Sri Lanka, Tayland, Myanmar) yaygın olan ve Pali Kanonu\'na dayanan en eski Budist okul hangisidir?', 'Theravada', ['Mahayana', 'Vajrayana', 'Zen'], 'Theravada \'yaşlıların öğretisi\' anlamına gelir; Pali dilindeki metinlere dayanır ve keşiş yaşamını öne çıkarır.'),
  ('Tibet\'te yaygın olan, mantra, mandala ve ritüelleri öne çıkaran Budizm koluna ne ad verilir?', 'Vajrayana', ['Theravada', 'Zen', 'Saf Toprak'], 'Vajrayana (\'Elmas Taşıt\') Tibet Budizminin temelidir; tantrik uygulamalar ve öğretmen-öğrenci ilişkisi merkezî önemdedir.'),
  ('Tibet Budizminde Dalay Lama\'nın seçimiyle ilgili geleneksel inanç hangisidir?', 'Önceki Dalay Lama\'nın yeniden doğmuş hâli olan bir çocuğun bulunması', ['Keşişlerin oylamasıyla en yaşlı keşişin seçilmesi', 'Unvanın babadan oğula geçmesi', 'Görevin, manastırda en uzun süre meditasyon yapmış ve en kıdemli keşişe verilmesi'], 'Tibet geleneğinde Dalay Lama\'nın, merhamet bodhisattvası Avalokiteşvara\'nın yeryüzündeki bedeni olduğuna ve ölünce yeniden doğduğuna inanılır; yeni Dalay Lama işaretlerle bir çocuk olarak bulunur.'),
  ('Theravada Budizminin Pali dilindeki kutsal metinlerinin oluşturduğu \'Üç Sepet\' adlı külliyat hangisidir?', 'Tripitaka', ['Tao Te Ching', 'Guru Granth Sahib', 'Lotus Sutra'], 'Tripitaka keşiş kurallarını (Vinaya), Buda\'nın vaazlarını (Sutta) ve felsefi açıklamaları (Abhidhamma) içeren üç bölümden oluşur.'),
  ('MÖ 3. yüzyılda Kalinga Savaşı\'ndaki kıyımdan pişmanlık duyup Budizmi benimseyen ve onu Hindistan dışına yayan Maurya hükümdarı kimdir?', 'Aşoka', ['Çandragupta', 'Kaniska', 'Harşa'], 'Aşoka, Kalinga Savaşı\'nın ardından şiddeti bırakmış, taş yazıtlarla Budist ahlakı yaymış ve Sri Lanka\'ya rahipler göndermiştir.'),
  ('Budist keşişlerin ve rahibelerin yaşam kurallarını içeren metinlere ve bu kurallara ne ad verilir?', 'Vinaya', ['Sutra', 'Koan', 'Mantra'], 'Vinaya, Sangha\'nın, yani keşiş topluluğunun yaşamını düzenleyen disiplin kurallarıdır; Tripitaka\'nın üç bölümünden biridir.'),
  ('Caynizmde öğretiyi yeniden canlandıran 24. ve son \'yol açıcı\' (tirthankara) sayılan, Buda ile aynı dönemde yaşamış kişi kimdir?', 'Mahavira', ['Guru Nanak', 'Laozi', 'Aşoka'], 'Vardhamana Mahavira, MÖ 6-5. yüzyılda yaşamış ve Caynizmde 24. tirthankara kabul edilmiştir.'),
  ('Bazı Cayn keşişlerinin ağızlarını bir bezle örtmesi ve yürürken önlerini süpürgeyle temizlemesi hangi ilkeyle açıklanır?', 'Böcekler dahil hiçbir canlıya istemeden zarar vermemek', ['Kutsal sözlerin yabancılarca duyulmasını önlemek', 'Tapınağa giriş için temizlik kuralına uymak', 'Kötü ruhları uzak tutmak'], 'Caynizm ahimsa ilkesini en uç biçimde uygular; keşişler küçük canlıları solumamak ya da ezmemek için bu önlemleri alır.'),
  ('Sihlerin son insan gurusu Guru Gobind Singh\'in ardından \'ebedî guru\' ilan edilen kutsal kitap hangisidir?', 'Guru Granth Sahib', ['Adi Purana', 'Bhagavad Gita', 'Dasam Granth'], 'Guru Gobind Singh, kendisinden sonra yaşayan bir guru olmayacağını, kutsal metin Guru Granth Sahib\'in ebedî guru olacağını bildirmiştir.'),
  ('Sihizmde dinî topluluğa girişi simgeleyen \'Khalsa\' kardeşliği kim tarafından ve hangi yılda kurulmuştur?', 'Guru Gobind Singh, 1699', ['Guru Nanak, 1499', 'Guru Arjan, 1604', 'Ranjit Singh, 1801'], 'Onuncu guru Gobind Singh 1699\'da Vaisakhi gününde Khalsa\'yı kurmuş ve beş inanç simgesini (beş K) belirlemiştir.'),
  ('Khalsa\'ya katılmış Sihlerin taşıdığı \'beş K\' arasında aşağıdakilerden hangisi yoktur?', 'Kalpak (keçe başlık)', ['Kesh (kesilmemiş saç)', 'Kara (çelik bilezik)', 'Kirpan (küçük kılıç)'], 'Beş K kesh (kesilmemiş saç), kangha (tarak), kara (bilezik), kirpan (kılıç) ve kachera (iç giysi)dir; kalpak bunlardan biri değildir.'),
  ('Sih erkeklerinin büyük çoğunluğunun sarık takmasının dinî gerekçesi nedir?', 'Kesilmeyen saçı örtüp korumak', ['Güneşten korunmak için getirilmiş bir askeri kural olması', 'Yalnız evli olduğunu göstermek', 'Kast düzenindeki yerini belirtmek'], 'Sihizmde saçın kesilmemesi (kesh) inanç simgesidir; sarık (dastar) bu saçı düzenli ve saygın biçimde örter.'),
  ('Konfüçyüs\'ün sözlerinin öğrencileri tarafından derlendiği eser hangisidir?', 'Konuşmalar', ['Tao Te Ching', 'Değişimler Kitabı', 'Savaş Sanatı'], 'Lunyu, yani Konuşmalar (Analektler), Konfüçyüs\'ün öğrencileriyle diyaloglarını ve sözlerini içeren temel eserdir.'),
  ('Konfüçyüsçülükte insanlar arasındaki ilişkilerde iyilik, insancıllık ve erdemi anlatan temel kavram hangisidir?', 'Ren', ['Wu wei', 'Qi', 'Dao'], 'Ren, \'insanlık, iyilikseverlik\' olarak çevrilir ve Konfüçyüsçü ahlakın merkezindeki erdemdir.'),
  ('Konfüçyüsçülükteki \'beş ilişki\' arasında aşağıdakilerden hangisi bulunmaz?', 'Keşiş ile tanrı', ['Hükümdar ile tebaa', 'Baba ile oğul', 'Arkadaş ile arkadaş'], 'Beş ilişki hükümdar-tebaa, baba-oğul, karı-koca, ağabey-kardeş ve arkadaş-arkadaş arasındaki ilişkilerdir.'),
  ('Konfüçyüsçülüğün Çin devlet yönetimini yüzyıllar boyunca etkilemesinin en somut örneği hangisidir?', 'Memur adaylarının Konfüçyüsçü klasiklerden sınava tabi tutulması', ['İmparatorların Budist keşişler arasından seçilmesi', 'Tapınakların vergi toplaması', 'Askerlerin Tao Te Ching\'i ezberlemesi'], 'Çin\'de imparatorluk sınav sistemi, devlet memurlarını Konfüçyüsçü klasiklere dayanan sınavlarla seçmiş ve 1905\'e kadar sürmüştür.'),
  ('Konfüçyüs\'e atfedilen \'Kendine yapılmasını istemediğin şeyi başkasına yapma\' sözü hangi evrensel ahlak ilkesinin bir biçimidir?', 'Altın kural', ['Kategorik buyruk', 'Fayda ilkesi', 'Toplum sözleşmesi'], 'Karşılıklılık ilkesi olarak da bilinen altın kural, farklı dinlerde ve düşünce sistemlerinde benzer biçimlerde görülür.'),
  ('Konfüçyüs\'ten sonra gelen ve insan doğasının özünde iyi olduğunu savunan Konfüçyüsçü düşünür kimdir?', 'Mencius', ['Xunzi', 'Laozi', 'Zhuangzi'], 'Mencius insanın doğuştan iyi olduğunu savunmuş; Xunzi ise insan doğasının kötü olduğunu ve eğitimle düzeltileceğini öne sürmüştür.'),
  ('\'Bir kelebek olduğunu düşleyen adam mı, yoksa adam olduğunu düşleyen bir kelebek mi?\' sorusuyla bilinen Taoist düşünür kimdir?', 'Zhuangzi', ['Konfüçyüs', 'Mencius', 'Sunzi'], 'Zhuangzi\'nin kelebek düşü öyküsü, gerçeklik ve kimlik algısının göreliliğini sorgulayan ünlü bir Taoist anlatıdır.'),
  ('Taoizm ile Konfüçyüsçülüğün toplumsal yaşama yaklaşımları karşılaştırıldığında hangisi doğrudur?', 'Konfüçyüsçülük törenleri ve kuralları, Taoizm doğallığı ve kendiliğindenliği öne çıkarır', ['İkisi de keşişliği zorunlu tutar', 'Taoizm katı devlet kurallarını ve törenleri, Konfüçyüsçülük ise yalnızlığı ve inzivayı savunur', 'İkisi de tek tanrıya ibadeti temel alır'], 'Konfüçyüsçülük ritüel (li) ve toplumsal düzen üzerinde dururken Taoizm yapay kuralları sorgulayıp doğaya uyumu savunur.'),
  ('Şinto geleneğine göre güneş tanrıçası Amaterasu\'ya adanmış en kutsal tapınak kompleksi hangisidir?', 'İse Büyük Tapınağı', ['Fuşimi İnari Tapınağı', 'Todai-ji', 'Kinkaku-ji'], 'İse Büyük Tapınağı, Şintonun en kutsal mekânıdır; iç tapınak geleneksel olarak 20 yılda bir yeniden inşa edilir.'),
  ('Şinto tapınaklarına giren ziyaretçilerin girişteki kaynakta ellerini ve ağzını yıkaması hangi Şinto kavramıyla ilişkilidir?', 'Arınma ve saflık', ['Ataların ruhuna sunu', 'Kötü ruhları korkutma', 'Kehanet'], 'Şintoda kirlilikten arınmak temel öneme sahiptir; temizuya denen kaynakta el ve ağız yıkamak bu arınmanın simgesidir.'),
  ('Japonya\'da Budizm ile Şintonun bir arada yaşaması, örneğin doğumların Şinto ve cenazelerin Budist törenlerle yapılması, hangi kavrama örnektir?', 'Senkretizm', ['Ateizm', 'Monoteizm', 'Köktencilik'], 'Japonya\'da yüzyıllar boyunca Şinto ve Budizm iç içe geçmiş; birçok kişi farklı yaşam olaylarında iki geleneğe de başvurur.'),
  ('Şamanların ruhlar dünyasına yolculuk sırasında ritim tutmak ve transa geçmek için kullandığı en önemli araç hangisidir?', 'Davul', ['Ney', 'Çan', 'Zil'], 'Şaman davulu (Türk boylarında \'tüngür\' ya da \'küpürge\') hem ritim tutar hem de şamanın ruhlar dünyasına yolculuğunda bineği sayılır.'),
  ('Haiti\'de Batı Afrika inançlarının Katolik unsurlarla kaynaşmasından doğan dinî geleneğe ne ad verilir?', 'Vodou', ['Santeria', 'Rastafari', 'Candomblé'], 'Haiti Vodou\'su, köleleştirilmiş Batı Afrikalıların inançlarının Katolik azizlerle eşleştirilmesiyle oluşmuştur; ruhlara \'lwa\' denir.'),
  ('1930\'larda Jamaika\'da ortaya çıkan ve Etiyopya İmparatoru Haile Selassie\'yi kutsal kabul eden hareket hangisidir?', 'Rastafari', ['Vodou', 'Santeria', 'Candomblé'], 'Rastafari hareketi, Haile Selassie\'nin taç giymeden önceki adı olan Ras Tafari\'den adını alır; Etiyopya\'yı vaat edilmiş topraklar olarak görür.'),
  ('Kuzey Amerika\'nın kuzeybatı kıyısındaki yerli halkların oyup diktiği totem direkleri genellikle neyi anlatır?', 'Bir klanın soyunu, öykülerini ve simgelerini', ['Tapınılan tek bir yaratıcı tanrıyı', 'Yalnız savaşlarda öldürülen düşmanların sayısını ve adlarını', 'Yıllık hasat miktarını'], 'Totem direkleri klan simgelerini, soy öykülerini ve önemli olayları anlatan anıtlardır; doğrudan tapınma nesnesi değildir.'),
  ('Kuzey Amerika yerlilerinin birçoğunda görülen, buhar dolu küçük bir kulübede dua ve arınma amacıyla yapılan tören hangisidir?', 'Ter kulübesi töreni', ['Hayalet Dansı', 'Potlatch', 'Güneş Dansı'], 'Ter kulübesi töreninde kızgın taşlara su dökülerek buhar oluşturulur; katılımcılar dua eder ve bedenen ve ruhen arınmayı amaçlar.'),
  ('Bir yürüyüşçü, Fransa\'dan başlayıp haftalarca yürüdüğü ve yol boyunca deniz kabuğu simgesini izlediği ünlü hac yolunun sonunda, Havari Büyük Yakup\'un mezarının bulunduğuna inanılan katedrale varıyor. Yürüyüşçü hangi şehre ulaşmıştır?', 'Santiago de Compostela', ['Lourdes', 'Fatima', 'Montserrat Manastırı'], 'Ortaçağ\'dan beri Avrupa\'nın her yerinden hacılar Camino de Santiago yollarını yürüyerek Santiago de Compostela Katedrali\'ne gelir.'),
  ('Hz. Ali\'nin türbesinin bulunduğu ve Şii Müslümanlar için en kutsal şehirlerden biri olan Irak şehri hangisidir?', 'Necef', ['Kerbela', 'Samarra', 'Bağdat'], 'Necef\'teki İmam Ali Türbesi Şii dünyasının en önemli ziyaret yerlerindendir; Hz. Hüseyin\'in türbesi ise Kerbela\'dadır.'),
  ('İran\'da Şiilerin sekizinci imamı İmam Rıza\'nın türbesinin bulunduğu şehir hangisidir?', 'Meşhed', ['Kum', 'İsfahan', 'Tebriz'], 'Meşhed, \'şehit düşülen yer\' anlamına gelir; İmam Rıza Türbesi İran\'ın en büyük ziyaret merkezidir.'),
  ('Myanmar\'ın Yangon şehrinde bulunan, altın kaplı devasa stupasıyla tanınan ve Buda\'nın saç tellerini barındırdığına inanılan tapınak hangisidir?', 'Şwedagon Pagodası', ['Angkor Vat', 'Borobudur', 'Mahabodhi Tapınağı'], 'Şwedagon Pagodası Myanmar\'ın en kutsal Budist mekânıdır; geleneğe göre içinde Buda\'nın sekiz tel saçı saklanır.'),
  ('Endonezya\'nın Cava adasında bulunan, basamaklı piramit biçiminde inşa edilmiş dünyanın en büyük Budist anıtı hangisidir?', 'Borobudur', ['Angkor Vat', 'Şwedagon', 'Prambanan'], '9. yüzyılda yapılan Borobudur, yüzlerce kabartma ve Buda heykeliyle bezeli dev bir stupa-mandala yapısıdır.'),
  ('Kamboçya\'daki Angkor Vat\'ın dinî tarihi açısından ilginç yanı nedir?', 'Hindu tapınağı olarak yapılıp Budist tapınağına dönüşmesi', ['Bir camiden kiliseye, ardından yeniden camiye dönüştürülmüş olması', 'Bir Şinto tapınağının kopyası olması', 'Hiçbir zaman ibadet için kullanılmamış olması'], 'Angkor Vat 12. yüzyılda Vişnu\'ya adanmış bir Hindu tapınağı olarak yapılmış, zamanla Theravada Budist tapınağı olarak kullanılmaya başlanmıştır.'),
  ('Osmanlı Devleti\'nde ilmiye sınıfının başı olan ve dinî konularda en yüksek fetva makamını temsil eden görevli kimdi?', 'Şeyhülislam', ['Kazasker', 'Nakibüleşraf', 'Reisülküttap'], 'Şeyhülislam Osmanlı\'da ilmiye teşkilatının başıydı; makam 1922\'de kaldırılmıştır.'),
  ('Ortodoks kiliselerinde büyük bir şehrin ve çevresindeki piskoposlukların başındaki din adamına ne ad verilir?', 'Metropolit', ['Kardinal', 'Diyakoz', 'Abbas'], 'Metropolit, Ortodoks kilise yapısında bir metropolün ve ona bağlı bölgenin başındaki üst düzey piskopostur.'),
  ('Hristiyan kiliselerinde rahibin altındaki ilk ruhban derecesi olan ve ayinde yardımcılık yapan görevliye ne ad verilir?', 'Diyakoz', ['Metropolit', 'Kardinal', 'Abbas'], 'Diyakoz (deacon), Yunanca \'hizmetkâr\' anlamına gelir; ayinde yardımcılık ve sosyal hizmet görevleri üstlenir.'),
  ('Bir Katolik manastırını yöneten keşişe verilen unvan hangisidir?', 'Abbas', ['Kardinal', 'Metropolit', 'Diyakoz'], 'Manastır başrahibine abbas (abbot) denir; Aramice \'baba\' anlamındaki abba sözcüğünden gelir.'),
  ('Sinagogda ibadet sırasında duaları ezgiyle okuyan görevliye ne ad verilir?', 'Kantor', ['Haham', 'Şamaş', 'Sofer'], 'Kantor ya da hazan, sinagog ayinlerinde duaları ezgiyle okuyarak cemaate önderlik eder.'),
  ('Mumbai\'deki bir ateş tapınağında beyaz giysili bir din adamı, kutsal ateşe sandal ağacı parçaları ekleyip törenleri yönetiyor. Zerdüşt geleneğinde bu din adamına ne ad verilir?', 'Mobed', ['Lama', 'Granthi', 'Brahmin'], 'Mobed, Zerdüşt din adamıdır; Sasani döneminde başmobed yüksek bir devlet görevlisiydi.'),
  ('Cami ile mescit arasındaki temel fark genellikle nasıl tanımlanır?', 'Camide cuma namazı kılınır ve minber bulunur, mescitte çoğu zaman bulunmaz', ['Mescitler yalnız kadınlar için yapılır', 'Camiler yalnız Osmanlı döneminde, mescitler ise yalnız Selçuklu döneminde yapılmıştır', 'Mescitte ezan okunması yasaktır'], 'Geleneksel kullanımda cuma ve bayram namazlarının kılındığı, minberli büyük ibadethanelere cami; daha küçük ve minbersiz olanlara mescit denir.'),
  ('Hindu tapınaklarına genel olarak verilen ad hangisidir?', 'Mandir', ['Gurdwara', 'Sinagog', 'Jinja'], 'Mandir, Hindu tapınağıdır; Güney Hindistan\'daki büyük tapınakların girişlerinde gopuram denen yüksek kapı kuleleri bulunur.'),
  ('Budizmi simgeleyen ve Buda\'nın öğretisini, çoğu zaman sekiz dilimli yolu temsil eden sekiz kollu çark hangisidir?', 'Dharmaçakra', ['Samsara çarkı', 'Ankh', 'Khanda'], 'Dharma çarkının sekiz kolu Sekiz Dilimli Yol\'u simgeler; Hindistan bayrağındaki Aşoka çarkı da bu simgeyle ilişkilidir.'),
  ('Ortasında çift kenarlı bir kılıç, çevresinde bir daire ve iki yanında birer kılıç bulunan Sih simgesi hangisidir?', 'Khanda', ['Ik Onkar', 'Om', 'Dharmaçakra'], 'Khanda, Sihizmin simgesidir; Sih bayrağı Nişan Sahib\'de yer alır. \'Ik Onkar\' ise \'Tek Tanrı vardır\' anlamına gelen yazılı simgedir.'),
  ('Vahiy kitabında anılan yedi kilisenin bulunduğu yerleri gezmek isteyen bir grup Efes, İzmir, Bergama, Akhisar, Sart, Alaşehir ve Denizli\'yi rotasına alıyor. Bu kiliseler toplu olarak hangi bölgededir?', 'Batı Anadolu', ['Karadeniz kıyısı', 'Güneydoğu Anadolu', 'Kapadokya'], 'Vahiy kitabındaki yedi kilise Efes, İzmir, Bergama, Tiyatira (Akhisar), Sardes, Filadelfiya (Alaşehir) ve Laodikya\'dır; hepsi Batı Anadolu\'dadır.'),
  ('Hem Hristiyan hem de İslam geleneğinde anlatılan, zulümden kaçıp bir mağarada yüzyıllarca uyuyan gençlerle ilgili kıssanın adı nedir?', 'Ashab-ı Kehf', ['Nuh Tufanı', 'Yunus peygamber ve balık kıssası', 'Sodom ve Gomora'], 'Yedi Uyurlar kıssası Hristiyan geleneğinde Efes\'le, Kur\'an\'daki Kehf suresinde ise \'mağara arkadaşları\' olarak anlatılır; Türkiye\'de birkaç yer bu mağarayla ilişkilendirilir.'),
  ('Mardin\'in Midyat ilçesinde bulunan, 397\'de kurulan ve dünyanın hâlâ faal en eski manastırlarından sayılan Süryani manastırı hangisidir?', 'Mor Gabriel Manastırı', ['Sümela Manastırı', 'Ahtamar Kilisesi', 'Sina\'daki Aziz Katerina Manastırı'], 'Mor Gabriel Manastırı, Tur Abdin bölgesinin dinî merkezidir ve kuruluşundan beri kesintisiz kullanılmaktadır.'),
  ('Van Gölü\'ndeki bir adada bulunan, 10. yüzyılda yapılmış ve dış duvarlarındaki Kutsal Kitap kabartmalarıyla ünlü Ermeni kilisesi hangisidir?', 'Akdamar Kilisesi', ['Ani Katedrali', 'Sümela Manastırı', 'Diyarbakır\'daki Surp Giragos Kilisesi'], 'Akdamar Adası\'ndaki Surp Haç Kilisesi, Vaspurakan Kralı Gagik döneminde yapılmıştır; Âdem ile Havva, Yunus, Davud ve Goliat gibi sahnelerin kabartmaları ünlüdür.'),
  ('Kapadokya\'daki kaya kiliseleri ve manastırların erken Hristiyanlık açısından önemi nedir?', 'Keşiş yaşamının ve fresk sanatının önemli bir merkezi olması', ['Hristiyanlığın ilk kez burada ortaya çıkması', 'İlk ekümenik konsilin burada toplanması ve inanç bildirgesinin yazılması', 'Papalık makamının bir süre burada bulunması'], 'Kapadokya\'daki yumuşak tüf kayalara oyulmuş kiliseler, Bizans keşiş topluluklarına ev sahipliği yapmış ve zengin fresk programlarıyla bilinir; Göreme Açık Hava Müzesi bunların başlıcasıdır.'),
  ('Yöneticileri 8-9. yüzyıllarda Yahudiliği benimseyen Türk devleti hangisidir?', 'Hazar Kağanlığı', ['Uygur Kağanlığı', 'Avar Kağanlığı', 'Karahanlı Devleti'], 'Hazar hükümdarları ve yönetici çevresi Yahudiliği benimsemiş; devlet içinde Müslüman, Hristiyan ve Gök Tanrı inancına bağlı topluluklar da yaşamıştır.'),
  ('Karahanlı hükümdarlarından Müslüman olan ve \'Abdülkerim\' adını alan kişi kimdir?', 'Satuk Buğra Han', ['Bilge Kağan', 'Tuğrul Bey', 'Alp Arslan'], 'Satuk Buğra Han, Müslüman olduktan sonra Abdülkerim adını almış ve Karahanlılarda İslamlaşmayı başlatmıştır.'),
  ('Moldova\'da yaşayan, Türkçe konuşan ve Ortodoks Hristiyan olan halk hangisidir?', 'Gagavuzlar', ['Karaylar', 'Kırım Tatarları', 'Çuvaşlar'], 'Gagavuzlar Türkçenin Oğuz grubundan bir dil konuşur ve Ortodoks Hristiyandır; Moldova\'da özerk Gagavuz Yeri bölgesinde yaşarlar.'),
  ('Osmanlı\'da hilafetin kaldırılmasıyla aynı gün, 3 Mart 1924\'te kurulan ve din işlerini yürütmekle görevlendirilen kurum hangisidir?', 'Diyanet İşleri Başkanlığı', ['Vakıflar Genel Müdürlüğü', 'Şeyhülislamlık', 'Evkaf Nezareti'], '3 Mart 1924\'te çıkarılan kanunlarla hilafet kaldırılmış, Şer\'iye ve Evkaf Vekâleti yerine Diyanet İşleri Reisliği kurulmuştur.'),
  ('Türkiye\'de tekke, zaviye ve türbelerin kapatılmasını öngören kanun hangi yıl çıkarılmıştır?', '1925', ['1924', '1934', '1946'], '677 sayılı kanunla 1925\'te tekke ve zaviyeler kapatılmış, şeyh, derviş gibi unvanların kullanılması yasaklanmıştır.'),
  ('Osmanlı Devleti\'nde gayrimüslim toplulukların kendi dinî önderleri aracılığıyla eğitim, evlilik ve miras gibi işlerini yürütmelerini sağlayan sisteme ne ad verilir?', 'Millet sistemi', ['Tımar sistemi', 'İltizam sistemi', 'Devşirme sistemi'], 'Millet sisteminde Rum Ortodoks, Ermeni ve Yahudi toplulukları kendi patrik ya da hahambaşıları aracılığıyla birçok iç işini yürütmüştür.'),
  ('Osmanlı\'da Yahudi toplumunun resmî dinî önderine verilen unvan hangisidir?', 'Hahambaşı', ['Patrik', 'Şeyhülislam', 'Metropolit'], 'Hahambaşılık makamı Osmanlı\'da Yahudi milletini devlete karşı temsil eder; Türkiye\'de bugün de sürmektedir.'),
  ('Osmanlı\'da vakıf kurumunun dinî yaşamdaki işlevi en iyi hangisiyle açıklanır?', 'Cami, medrese, imaret gibi yapıların masraflarını gelirle karşılayarak sürekliliğini sağlaması', ['Din adamlarının maaşlarını yalnız devlet hazinesinden ödemesi', 'Tarikatları denetleyen bir mahkeme olması', 'Hac yolculuklarını yasaklaması'], 'Vakıflar, bir mülkün gelirini kalıcı olarak hayır işlerine ayırarak ibadethane, eğitim ve sosyal yardım kurumlarının yüzyıllarca işlemesini sağlamıştır.'),
  ('Yavuz Sultan Selim\'in 1517 Mısır seferinden sonra İstanbul\'a getirilen ve bugün Topkapı Sarayı\'nda korunan dinî emanetlere genel olarak ne ad verilir?', 'Mukaddes Emanetler', ['Surre', 'Hazine-i Hassa', 'Hırka-i Saadet Dairesi kitapları'], 'Hz. Muhammed\'e ait olduğu kabul edilen hırka, sancak, kılıçlar gibi eşyalar Mukaddes Emanetler olarak Topkapı Sarayı\'nda korunur.'),
  ('Brezilya\'daki bir törende Yoruba ruhlarının Katolik azizlerle özdeşleştirildiği ve iki geleneğin dualarının birlikte okunduğu görülüyor. Bu durum hangi kavrama örnektir?', 'Senkretizm', ['Ekümenizm', 'Sekülerleşme', 'Köktencilik'], 'Senkretizm, farklı inanç öğelerinin kaynaşmasıdır; Santeria ve Japonya\'daki Şinto-Budizm birlikteliği bunun örnekleridir.'),
  ('Yahudi geleneğinde Davud soyundan geleceğine ve İsrail\'i kurtaracağına inanılan kişiye verilen ve İbranice \'meshedilmiş\' anlamına gelen unvan hangisidir?', 'Mesih', ['Haham', 'Levili', 'Nazir'], 'Mesih (Maşiah), kutsal yağla meshedilmiş kral anlamına gelir; Yunancası \'Khristos\'tur ve Hristiyanlık adını bu sözcükten alır.'),
  ('Bir dinin resmî olarak kutsal kabul ettiği metinlerin listesine ne ad verilir?', 'Kanon', ['Apokrif', 'Tefsir', 'Dogma'], 'Kanon, Yunanca \'ölçü, kural\' demektir; kilisenin kutsal kitap olarak kabul ettiği metinlerin listesini anlatır. Kanona alınmayanlara apokrif denir.'),
  ('Bir dinin resmî otoritesince kabul edilen öğretiden sapma sayılan görüşe Hristiyan tarihinde ne ad verilmiştir?', 'Sapkınlık (heretik görüş)', ['Ortodoksi (doğru öğreti)', 'Kanon', 'Konsil'], 'Hristiyan tarihinde konsillerin reddettiği Ariusçuluk gibi görüşler heretik (sapkın) sayılmıştır; \'ortodoksi\' ise doğru kabul edilen öğretiyi anlatır.'),
  ('Bir dinin inançlarını akla dayalı olarak savunma ve eleştirilere yanıt verme çabasına ne ad verilir?', 'Apologetik', ['Teodise', 'Ekümenizm', 'Eskatoloji'], 'Apologetik, Yunanca \'savunma\' anlamındaki apologia\'dan gelir; erken Hristiyan apolojistleri inançlarını Roma\'ya karşı savunmuştur.'),
  ('İslam\'da yeni doğan bebeğin sağ kulağına ezan, sol kulağına kamet okunarak adının konması geleneği hangi amacı taşır?', 'Bebeğin hayata Allah\'ın adı ve ibadete çağrıyla başlaması', ['Bebeğin vaftiz edilmesini sağlamak', 'Bebeğin ileride hangi mezhebe ve hangi tarikata bağlı olacağını belirlemek', 'Bebeğin doğum gününü kutlamak'], 'Ad koyma sırasında okunan ezan ve kamet, bebeğin duyduğu ilk sözlerin tevhit ve namaza çağrı olması anlamını taşır.'),
  ('İslam geleneğinde vefat eden kişinin cenaze namazıyla ilgili hangisi doğrudur?', 'Rükû ve secde olmadan ayakta tekbirlerle kılınır', ['Yalnız akrabalar tarafından, rükû ve secdeyle birlikte kılınır', 'Ölümden kırk gün sonra kılınır', 'Yalnız camide ve cuma günü kılınabilir'], 'Cenaze namazı dört tekbirle ayakta kılınır; rükû ve secdesi yoktur ve genellikle defin öncesinde kılınır.'),
  ('İslam ve Yahudilikte ölünün cenaze işlemleriyle ilgili ortak bir gelenek hangisidir?', 'Ölünün yıkanıp kefenlenerek çabucak gömülmesi', ['Ölünün yakılıp küllerinin nehre bırakılması', 'Ölünün mumyalanarak aile mezarında yıllarca saklanması', 'Ölünün akbabalara bırakılması'], 'İki gelenekte de ölü yıkanır, sade bir kefene sarılır ve gömme işlemi geciktirilmeden yapılır; yakma geleneksel olarak kabul edilmez.'),
  ('Tibet\'te kayalık arazide toprağın donması ve yakacak odun azlığı gibi nedenlerle uygulanan, ölünün bedeninin kuşlara bırakıldığı cenaze geleneğine ne ad verilir?', 'Gök gömme', ['Deniz gömme', 'Mumyalama', 'Kremasyon'], 'Gök gömme (jhator), Budist anlayışta bedenin boş bir kap olduğu düşüncesiyle de ilişkilidir; ceset akbabalara bırakılır.'),
  ('1830\'da ABD\'de Joseph Smith tarafından kurulan ve merkezi Utah\'taki Salt Lake City olan dinî topluluk hangisidir?', 'Mormon Kilisesi', ['Yehova Şahitleri', 'Yedinci Gün Adventistleri', 'Hristiyan Bilimi'], 'Mormon Kilisesi, Joseph Smith\'in yayımladığı Mormon Kitabı\'na dayanır; Brigham Young önderliğinde Utah\'a göç etmiştir.'),
  ('Cumartesiyi dinlenme ve ibadet günü kabul eden, sağlıklı beslenmeye önem verip çoğu üyesi vejetaryen olan Protestan kökenli topluluk hangisidir?', 'Adventistler', ['Mormonlar', 'Kuakerler', 'Amişler'], 'Adventistler adlarını İsa\'nın ikinci gelişini (advent) beklemelerinden alır; cumartesiyi Sebt günü olarak tutar ve sağlık reformunu öne çıkarır.'),
  ('İngiltere\'de 1865\'te William Booth\'un kurduğu, askerî rütbe ve üniformalarla örgütlenen ve sosyal yardım çalışmalarıyla tanınan Hristiyan topluluk hangisidir?', 'Kurtuluş Ordusu', ['Cizvitler', 'Tapınak Şövalyeleri', 'Kızılhaç'], 'Kurtuluş Ordusu, yoksullara yönelik yardım çalışmalarıyla tanınır; üyeleri askerî unvanlar kullanır.'),
  ('Ortaçağ\'da Kudüs\'e giden hacıları korumak amacıyla kurulan ve hem keşiş hem asker olan üyelerden oluşan tarikat hangisidir?', 'Tapınak Şövalyeleri', ['Fransiskenler', 'Benediktenler', 'Kartuziyenler'], 'Tapınak Şövalyeleri 1119 civarında kurulmuş, Kudüs\'teki Mabet Tepesi\'nde konuşlandıkları için bu adı almıştır; 1312\'de papa tarafından kaldırılmıştır.'),
  ('Katolik geleneğinde ölüler için yapılan ayinin müziğine ve bu türdeki bestelere ne ad verilir?', 'Rekuiem', ['Oratoryo', 'Kantat', 'Te Deum'], 'Rekuiem adını ayinin Latince ilk sözcüğü \'requiem\' (huzur)\'dan alır; Mozart ve Verdi\'nin rekuiemleri ünlüdür.'),
  ('İslam sanatında canlı figür yerine sıkça hat, geometrik desen ve bitkisel süslemenin tercih edilmesi en çok neyle açıklanır?', 'Dinî mekânlarda suret yapımından kaçınma anlayışıyla', ['Boya maddelerinin yetersizliğiyle', 'Ressamların yalnız saraylarda ve padişah izniyle çalışabilmesiyle', 'Geometrinin henüz bilinmemesiyle'], 'Özellikle dinî mekânlarda canlı tasvirinden kaçınma eğilimi, hat, geometrik geçmeler ve arabesk gibi soyut süsleme sanatlarının gelişmesine yol açmıştır; minyatür gibi alanlarda figür yine kullanılmıştır.'),
  ('Hint geleneğinde tanrıların adlarının ve ilahilerin topluca, çağrı-yanıt biçiminde ve çalgı eşliğinde söylendiği ibadet müziğine ne ad verilir?', 'Kirtan', ['Raga', 'Gazel', 'Kantat'], 'Kirtan, Bhakti (sevgiyle bağlılık) geleneğinin topluca söylenen ilahileridir; Sih geleneğinde de Guru Granth Sahib\'den ilahiler kirtan olarak okunur.'),
  ('İslam fıkhında \'mekruh\' kavramı neyi anlatır?', 'Kesin yasak olmayan ama terk edilmesi iyi görülen şeyi', ['Kesin olarak farz olan ibadeti', 'Kesin olarak yasaklanmış şeyi', 'Yalnız bayramlarda ve yolculuk sırasında serbest olan şeyi'], 'Mekruh, haram kadar kesin olmayan, terk edilmesi tavsiye edilen davranışları anlatır.'),
  ('Katolik gelenekte uzun süre cuma günleri hangi yiyecekten kaçınılmış, yerine çoğu zaman balık yenmiştir?', 'Kırmızı et ve tavuk etinden', ['Ekmekten', 'Sebze ve zeytinyağlı yemeklerden', 'Balıktan'], 'İsa\'nın çarmıha gerildiği güne saygı olarak cuma günleri sıcakkanlı hayvan eti yenmez; balık bu kurala girmediğinden cuma balığı geleneği doğmuştur.'),
  ('İslam düşüncesinde inanç esaslarını akli ve nakli delillerle savunan ve açıklayan ilim dalına ne ad verilir?', 'Kelam', ['Fıkıh', 'Tefsir', 'Siyer'], 'Kelam, Allah\'ın varlığı ve sıfatları, peygamberlik ve ahiret gibi inanç konularını akli delillerle temellendirmeye çalışan ilimdir.'),
  ('\'Filozofların Tutarsızlığı\' (Tehâfütü\'l-Felâsife) adlı eseriyle bazı felsefi görüşleri eleştiren ve \'İhya-u Ulumi\'d-Din\' ile tasavvufu ana akım düşünceye yaklaştıran âlim kimdir?', 'İmam Gazali', ['İbn Rüşd', 'Farabi', 'İbn Sina'], '11. yüzyılda yaşayan Gazali, Nizamiye Medresesi\'nde ders vermiş; filozofları eleştirmiş ve tasavvufu Sünni düşünceyle uzlaştırmıştır.'),
  ('Gazali\'nin \'Filozofların Tutarsızlığı\'na \'Tutarsızlığın Tutarsızlığı\' (Tehâfütü\'t-Tehâfüt) adlı eseriyle yanıt veren Endülüslü filozof kimdir?', 'İbn Rüşd', ['İbn Haldun', 'İbn Tufeyl', 'Kindi'], 'Kurtubalı İbn Rüşd (Averroes), Aristoteles şerhleriyle Avrupa\'da da etkili olmuş ve felsefeyi Gazali\'nin eleştirilerine karşı savunmuştur.'),
  ('Tasavvuf tarihinde \'Ene\'l-Hak\' (Ben Hakk\'ım) sözü nedeniyle 922\'de Bağdat\'ta idam edilen sufi kimdir?', 'Hallac-ı Mansur', ['Rabiatü\'l-Adeviyye', 'Cüneyd-i Bağdadi', 'Bayezid-i Bistami'], 'Hallac-ı Mansur\'un bu sözü, kendi benliğinden geçip Tanrı\'da yok olma deneyiminin ifadesi olarak yorumlanmış; ancak döneminde küfür sayılarak idamına yol açmıştır.'),
  ('Erken İslam döneminde Kur\'an\'dan sonra en çok güvenilen kaynaklardan sayılan ve Hz. Muhammed\'in hayatını gören kuşağa verilen ad hangisidir?', 'Sahabe', ['Tabiin', 'Ensar', 'Müçtehit'], 'Hz. Muhammed\'i görüp onunla sohbet eden Müslümanlara sahabe; sahabeyi görenlere tabiin denir.'),
  ('Sahabeyi görmüş ve onlardan bilgi almış, ancak Hz. Muhammed\'i görmemiş Müslüman kuşağa ne ad verilir?', 'Tabiin', ['Sahabe', 'Muhacir', 'Ensar'], 'Tabiin \'tabi olanlar\' demektir; Hasan-ı Basri gibi ünlü âlimler bu kuşaktandır.'),
  ('İslam\'da Hz. Muhammed\'in ailesini, özellikle Hz. Ali, Hz. Fatıma, Hz. Hasan ve Hz. Hüseyin\'i anlatan kavram hangisidir?', 'Ehl-i Beyt', ['Ashab-ı Suffa', 'Hulefa-i Raşidin', 'Aşere-i Mübeşşere'], 'Ehl-i Beyt \'ev halkı\' demektir; Alevilik ve Şiilikte Ehl-i Beyt sevgisi inancın merkezindedir, Sünniler de Ehl-i Beyt\'e büyük saygı gösterir.'),
  ('Ankara\'da yaşamış ve Osmanlı\'nın kuruluş döneminde etkili olan, Fatih\'in hocası Akşemseddin\'in de bağlı olduğu tarikatın kurucusu Hacı Bayram-ı Veli\'nin türbesi nerededir?', 'Ankara\'da, Hacı Bayram Camii\'nin yanında', ['Konya\'da Mevlânâ Müzesi\'nde', 'Bursa\'da Emir Sultan Camii\'nde', 'Kırşehir\'de, Ahi Evran Camii\'nin avlusunda'], 'Hacı Bayram-ı Veli\'nin türbesi, Ankara Ulus\'taki Hacı Bayram Camii\'nin bitişiğinde, Augustus Tapınağı\'nın yanındadır.'),
  ('Osmanlı\'da \'Hamzaviler\' gibi kollarıyla bilinen, kendini gizlemeyi ve gösterişten kaçmayı ilke edinen tasavvuf anlayışı hangisidir?', 'Melamilik', ['Mevlevilik', 'Rifailik', 'Kadirilik'], 'Melamilik, kişinin manevi hâllerini gizlemesini, kınanmayı göze alıp riyadan kaçınmasını öğütleyen tasavvuf anlayışıdır.'),
  ('Tasavvufta bir dervişin şeyhine bağlılığını ifade eden \'biat\' ya da \'intisap\' kavramı neyi anlatır?', 'Bir mürşide bağlanarak tarikata girmeyi', ['Tarikattan ayrılıp yeni bir tarikat kurmayı', 'Şeyhin ölümünden sonra mirasını paylaşmayı', 'Dervişin kırk günlük çileyi tamamlamasını'], 'İntisap, bir müridin bir şeyhe el vererek (biat) tarikata girmesidir; bu bağlılık silsile denen manevi zincire katılmak anlamına gelir.'),
  ('Tarikatlarda şeyhten başlayarak Hz. Muhammed\'e kadar uzanan manevi öğretmenler zincirine ne ad verilir?', 'Silsile', ['İsnad', 'Şecere-i Türk', 'Halife'], 'Silsile, tarikatın öğretisinin kuşaktan kuşağa aktarıldığı manevi zincirdir; hadis bilimindeki isnad kavramına benzer.'),
  ('Tevrat\'a göre Musa\'nın kardeşi olan ve İsrail\'in ilk başkâhini sayılan kişi kimdir?', 'Harun', ['Yuşa', 'Kâleb', 'Levi'], 'Harun (Aaron), Musa\'nın ağabeyidir; soyundan gelenler (kohenler) tapınakta kâhinlik yapmıştır.'),
  ('Tevrat anlatısında On Emir\'in yazılı olduğu levhaların saklandığı kutsal sandık hangi adla bilinir?', 'Ahit Sandığı', ['Kutsal Kâse', 'Menora', 'Tabernakl çanı'], 'Ahit Sandığı On Emir levhalarını taşıyan altın kaplı sandıktır; Süleyman Mabedi\'nin en iç bölümünde (Kodeşü\'l-Kodeşim) saklandığı anlatılır.'),
  ('Kudüs\'ü başkent yapan ve İslam geleneğinde de peygamber kabul edilen İsrail kralı kimdir?', 'Davud', ['Saul', 'Süleyman', 'Yeroboam'], 'Geleneğe göre Davud Kudüs\'ü alıp başkent yapmış, oğlu Süleyman ise orada Birinci Mabet\'i inşa etmiştir.'),
  ('\'Yahudi\' adı köken olarak neyden gelir?', 'Yehuda kabilesinin ve krallığının adından', ['Musa\'nın oğlunun adından', 'Kudüs\'ün eski adından', 'İbranicede \'kitap ehli\' anlamına gelen eski bir sözcükten'], 'Yahudi adı, Yakup\'un oğlu Yehuda\'nın adını taşıyan kabile ve güneydeki Yehuda Krallığı\'ndan gelir.'),
  ('Hristiyan öğretisinde İsa\'nın çarmıhtaki ölümünün insanlığın günahlarına karşılık bir bedel olduğu inancına ne ad verilir?', 'Kefaret', ['Enkarnasyon', 'Teslis', 'Transubstantiasyon'], 'Kefaret öğretisine göre İsa\'nın ölümü insanlığı günahtan kurtaran bir fidye ya da bedeldir.'),
  ('Hristiyan öğretisinde Âdem ile Havva\'nın itaatsizliği sonucu bütün insanlığa geçtiğine inanılan günaha ne ad verilir?', 'Asli günah', ['Ölümcül günah', 'Bağışlanabilir günah', 'Meleklerin günahı'], 'Asli günah öğretisini özellikle Augustinus geliştirmiştir; İslam bu görüşü kabul etmez ve her insanın günahsız doğduğunu savunur.'),
  ('Katolik öğretide cennete gitmeden önce bazı ruhların arınmak için geçici olarak bulunduğu yere ne ad verilir?', 'Purgatoryum (Araf)', ['Limbo', 'Hades (yeraltı dünyası)', 'Gehenna'], 'Purgatoryum Katolik öğretisinde arınma yeridir; Protestanlar bunu kabul etmez. Endüljans tartışması da bu öğretiyle bağlantılıdır.'),
  ('Hristiyan geleneğinde İsa\'nın dirilişinden kırk gün sonra semaya alınışını anan inanç ve bayram hangi adla bilinir?', 'Asensiyon (Göğe Yükseliş)', ['Diriliş', 'Enkarnasyon', 'Pentekost (Hamsin yortusu)'], 'Elçilerin İşleri\'ne göre İsa dirildikten kırk gün sonra göğe yükselmiştir; Pentekost ise elli gün sonra Kutsal Ruh\'un inişini anar.'),
  ('Hristiyanlıkta pazar gününün ibadet günü olarak benimsenmesinin dinî gerekçesi nedir?', 'İsa\'nın haftanın ilk günü dirildiğine inanılması', ['Roma\'da pazar gününün eskiden beri pazar kurma ve tatil günü olması', 'Yahudi Şabat\'ının pazara denk gelmesi', 'Musa\'nın On Emir\'i pazar günü alması'], 'İncillere göre İsa haftanın ilk günü dirilmiştir; erken Hristiyanlar bu günü \'Rabbin günü\' olarak anmıştır.'),
  ('İslam\'da cumanın, Yahudilikte cumartesinin, Hristiyanlıkta pazarın öne çıkması hangi ortak özelliği gösterir?', 'Üç dinin de haftalık ortak ibadet için bir gün belirlemesi', ['Üç dinde de o gün her türlü çalışmanın kesinlikle yasak olması', 'Üç dinin de aynı takvimi kullanması', 'Üç dinde de o gün oruç tutulması'], 'Üç İbrahimî din haftanın bir gününü topluca ibadete ayırır; ancak İslam\'da cuma tam dinlenme günü değildir, Şabat ise iş yasaklarını içerir.'),
  ('Hristiyan kiliselerinde ayin sırasında giyilen, rengi litürjik döneme göre değişen kolsuz üst giysiye ne ad verilir?', 'Kazula', ['Sutan', 'Kukulla', 'Kipa'], 'Kazula, rahibin ayinde giydiği dış giysidir; renkleri dönemlere göre değişir: örneğin mor perhiz, beyaz bayram dönemlerinde kullanılır.'),
  ('Bir Katolik rahip adayına, rahip olarak atandıktan sonra evlenemeyeceği ve bekâr bir yaşam sürmesi gerektiği söyleniyor. Bu kurala ne ad verilir?', 'Selibat', ['Abstinans', 'Tonsür', 'Ordinasyon'], 'Batı kilisesinde rahiplerin bekâr kalması kuralı (selibat) 12. yüzyılda kesinleşmiştir; Doğu kiliselerinde evli rahiplik mümkündür.'),
  ('İstanbul\'daki Eyüp Sultan Türbesi, kimin mezarı olarak kabul edilir?', 'Ebu Eyyub el-Ensari', ['Hz. Hamza', 'Ebu Hureyre', 'Selman-ı Farisi'], 'Ebu Eyyub el-Ensari, hicrette Hz. Muhammed\'i evinde ağırlayan sahabedir; 7. yüzyıldaki İstanbul kuşatmasında vefat etmiş, türbesi fetihten sonra yaptırılmıştır.'),
  ('Tarsus\'ta bugün ziyaret edilen ve bir kilisenin adını taşıyan kuyu hangi kişiyle ilişkilendirilir?', 'Aziz Pavlus', ['Aziz Petrus', 'Aziz Nikolaos', 'Aziz Yuhanna'], 'Tarsus, Pavlus\'un doğduğu şehirdir; şehirde onun adını taşıyan kuyu ve Aziz Pavlus Kilisesi Hristiyan ziyaretçilerin uğrak yerleridir.'),
  ('Neolitik döneme ait Göbeklitepe\'deki T biçimli dikilitaşların din tarihi açısından en çok tartışılan yorumu hangisidir?', 'Avcı-toplayıcıların topluca kullandığı bir kült ve tören alanı olabileceği', ['Bir krallık sarayının duvarları olduğu', 'Bir Roma tapınağının temelleri olduğu', 'Bir Bizans manastırının kalıntıları olduğu'], 'Klaus Schmidt başta olmak üzere araştırmacılar, Göbeklitepe\'nin avcı-toplayıcıların ortak törenler için kullandığı anıtsal bir alan olabileceğini öne sürmüştür; işlevi hâlâ tartışılmaktadır.'),
  ('Neandertal ve erken insanların ölülerini çiçek ya da eşyalarla birlikte gömmesi din tarihçileri tarafından nasıl yorumlanır?', 'Ölümden sonraki yaşama dair erken bir inancın işareti olabileceği', ['Yazının icat edildiğinin kanıtı olduğu', 'Tek tanrılı inancın başladığı', 'Tarımın yaygınlaştığının kanıtı olduğu'], 'Bilinçli gömme ve mezara eşya bırakma, ölüme özel anlam yükleyen düşüncenin ve belki öbür dünya inancının en eski izlerinden sayılır; ancak yorumlar tartışmalıdır.'),
  ('Taş Devri\'nden kalan, iri kalçalı ve göğüslü küçük kadın heykelciklerinin bir yorumu nedir?', 'Bereket ve doğurganlıkla ilişkili inançları yansıtabilecekleri', ['Kraliçeleri tasvir eden resmî portreler oldukları', 'Savaş tanrıçası heykelleri oldukları', 'Çocuk oyuncağı olarak üretildikleri'], 'Willendorf Venüsü gibi heykelcikler sıklıkla bereket ve doğurganlık simgeleri olarak yorumlanır; kesin işlevleri bilinmemektedir.'),
  ('İngiltere\'deki Stonehenge\'in taşlarının yaz gündönümünde güneşin doğuşuyla hizalanması hangi tür inanç ve uygulamalarla ilişkilendirilir?', 'Güneş döngüsüne bağlı törenler ve takvimsel ritüeller', ['Tek tanrılı bir dinin ibadetleri', 'Ortaçağ manastır yaşamı', 'Roma imparator kültü'], 'Stonehenge\'in gündönümleriyle hizalanması, güneş ve mevsim döngüsüne bağlı törensel kullanıma işaret eder; yapının kesin dinî işlevi bilinmemektedir.'),
  ('Aşağıdaki dinlerden hangisinde kutsal metin ve ibadet dili olarak ağırlıkla Sanskritçe kullanılır?', 'Hinduizm', ['Sihizm', 'Theravada Budizmi', 'Zerdüştlük'], 'Vedalar ve Upanişadlar Sanskritçedir; Theravada metinleri Pali, Guru Granth Sahib Gurmukhi yazılı Pencapça ağırlıklı, Avesta ise Avestaca ile yazılmıştır.'),
  ('Buda\'nın öldüğü ve nihai nirvanaya (parinirvana) ulaştığı kabul edilen yer hangisidir?', 'Kuşinagar', ['Sarnath', 'Lumbini', 'Bodh Gaya'], 'Buda yaklaşık 80 yaşında Kuşinagar\'da ölmüştür; Lumbini, Bodh Gaya, Sarnath ve Kuşinagar dört büyük Budist hac yeridir.'),
  ('Çin\'in Henan eyaletinde bulunan, Chan (Zen) Budizminin beşiklerinden sayılan ve dövüş sanatlarıyla ünlü manastır hangisidir?', 'Şaolin Manastırı', ['Potala Sarayı', 'Todai-ji', 'Wat Pho'], 'Şaolin Manastırı, geleneğe göre Bodhidharma\'nın meditasyon yaptığı yerdir ve keşişlerinin kung fu geleneğiyle ünlüdür.'),
  ('Tibet\'in Lhasa şehrinde bulunan ve tarih boyunca Dalay Lamaların kışlık sarayı olarak kullanılmış yapı hangisidir?', 'Potala Sarayı', ['Şaolin Manastırı', 'Şwedagon Pagodası', 'Jokhang Tapınağı'], 'Potala Sarayı 17. yüzyılda V. Dalay Lama döneminde bugünkü biçimini almış, 1959\'a kadar Dalay Lamaların resmî ikametgâhı olmuştur.'),
  ('Bir Hindu topluluğu, Krişna\'ya duydukları sevgiyi coşkulu ilahiler, dans ve sürekli anma yoluyla ifade ediyor; onlara göre kurtuluşun yolu bu içten bağlılıktır. Bu akıma ne ad verilir?', 'Bhakti', ['Advaita', 'Tantra', 'Ahimsa'], 'Bhakti \'sevgiyle bağlılık\' demektir; ilahiler, kirtan ve ibadetle tanrıya duyulan kişisel sevgiyi merkeze alır.'),
  ('Hinduizmde \'yoga\' terimi geleneksel olarak en geniş anlamıyla neyi ifade eder?', 'Bireyi kurtuluşa götüren manevi disiplin ve yöntemleri', ['Yalnız beden esnekliği için yapılan egzersizleri', 'Bir tanrıya sunulan kurban törenini', 'Kast sistemindeki bir sınıfı'], 'Yoga \'birleştirme, boyunduruk\' anlamına gelir; bilgi (jnana), eylem (karma), bağlılık (bhakti) ve meditasyon (raja) yogası gibi manevi yolları kapsar.'),
  ('Hinduizmde tanrıça Durga, Kali ve Parvati gibi dişil tanrısal gücü anlatan kavram hangisidir?', 'Şakti', ['Atman', 'Dharma', 'Avatar'], 'Şakti, tanrısal enerjinin dişil yönüdür; Şaktizm tanrıçayı yüce gerçeklik olarak kabul eden Hindu geleneğidir.'),
  ('Ramayana destanında Rama\'nın sadık yardımcısı olan ve maymun biçiminde tasvir edilen figür kimdir?', 'Hanuman', ['Ganeşa', 'Krişna', 'Garuda'], 'Hanuman güç ve bağlılığın simgesidir; Rama\'nın eşi Sita\'yı kurtarmaya yardım eder.'),
  ('Ortodoks kiliselerinde ayin sırasında cemaatin genellikle nasıl durduğu bilinir?', 'Geleneksel olarak ayakta durarak', ['Yere bağdaş kurarak', 'Yalnız diz çökerek', 'Sıralara oturup hiç kalkmayarak'], 'Geleneksel Ortodoks kiliselerinde oturma sıraları azdır ya da yoktur; cemaat ayini çoğunlukla ayakta izler.'),
  ('Ortodoks dünyasında İstanbul\'un 1453\'te Osmanlılara geçmesinden sonra kendini \'Üçüncü Roma\' olarak gören şehir hangisidir?', 'Moskova', ['Kiev', 'Belgrad', 'Sofya'], '15-16. yüzyılda Rus din adamları, Roma ve Konstantinopolis\'ten sonra Ortodoksluğun koruyucusunun Moskova olduğunu ileri sürmüştür.'),
  ('Slav halklarına Hristiyanlığı yaymak için 9. yüzyılda çalışan ve Kiril alfabesinin dayandığı Glagolitik yazıyı geliştirdikleri kabul edilen kardeşler kimlerdir?', 'Kiril ve Metodiy', ['Petrus ve Andreas', 'Benedictus ve Scholastica', 'Cosmas ve Damianus'], 'Selanikli Kiril ve Metodiy, Slav dilinde ayin yapılabilmesi için yazı geliştirmiştir; Kiril alfabesi adını Kiril\'den alır.'),
  ('988\'de Kiev Prensi I. Vladimir\'in Ortodoks Hristiyanlığı kabul etmesinin uzun vadeli sonucu hangisidir?', 'Rus, Ukrayna ve Belarus topraklarında Ortodoksluğun yerleşmesi', ['Rusya\'nın Katolik dünyasına katılması', 'Kiev\'in papalık merkezi olması', 'Slav halklarının İslam\'ı benimsemesi'], 'Kiev Rus\'unun vaftizi, Doğu Slav topraklarının Bizans Ortodoks geleneğine bağlanmasını sağlamış ve bu bölgelerin kültürünü derinden etkilemiştir.'),
  ('Bir Kur\'an kursunda öğrencilere harflerin ağızdaki çıkış yerleri, hangi harfin ne kadar uzatılacağı ve nerede durulacağı öğretiliyor. Öğretilen ilmin adı nedir?', 'Tecvit', ['Tefsir', 'Fıkıh', 'Kelam'], 'Tecvit, harflerin çıkış yerleri, uzatmalar ve duraklar gibi kurallarla Kur\'an\'ın doğru okunmasını öğreten ilimdir.'),
  ('Kur\'an\'ın bir dile çevirisinin İslam geleneğinde genellikle \'meal\' olarak adlandırılmasının nedeni nedir?', 'Çevirinin Kur\'an\'ın kendisi değil, anlamının aktarımı sayılması', ['Çevirilerin yalnız Türkçe yapılabilmesi', 'Mealin yalnız ilk sureyi kapsaması', 'Çevirilerin namazda okunmasının zorunlu olması'], 'Meal \'anlam\' demektir; İslam geleneğinde Kur\'an\'ın Arapça metni asıl kabul edilir, çeviriler ise anlamın yaklaşık aktarımı sayılır.'),
  ('İslam\'da Hz. Muhammed için okunan \'Allahümme salli ala Muhammed\' gibi dualara ne ad verilir?', 'Salavat', ['Tekbir', 'Besmele', 'Kamet'], 'Salavat, Hz. Muhammed\'e rahmet ve esenlik dilemek için okunan dualardır.'),
  ('Ramazan\'ın son on gününde bir kişi işinden izin alıp gece gündüz camide kalıyor, yalnız zorunlu ihtiyaçları için dışarı çıkıyor ve vaktini ibadetle geçiriyor. Bu ibadetin adı nedir?', 'İtikâf', ['Teravih', 'Mukabele', 'Fitre'], 'İtikâf, belli bir süre camide kalıp ibadet ve tefekkürle meşgul olmaktır; özellikle Ramazan\'ın son on gününde yapılır.'),
  ('İslam\'da farz ve vacip dışında, kişinin kendi isteğiyle kıldığı ek namazlara genel olarak ne ad verilir?', 'Nafile', ['Farz', 'Kaza', 'Vacip'], 'Nafile namazlar zorunlu olmayan, sevap için kılınan ek namazlardır.'),
  ('Konfüçyüs\'ün doğduğu ve büyük tapınağıyla ailesinin mezarlığının bulunduğu Çin şehri hangisidir?', 'Qufu', ['Pekin', 'Şian', 'Nankin'], 'Shandong eyaletindeki Qufu\'da Konfüçyüs Tapınağı, Kong ailesinin konağı ve mezarlığı bulunur; üçü birlikte UNESCO Dünya Mirası listesindedir.'),
  ('Sınava hazırlanan Japon bir öğrenci, bir Şinto tapınağından başarı için kutsandığına inanılan küçük kumaş bir torba alıp çantasına asıyor. Bu nesnenin adı nedir?', 'Omamori', ['Shimenawa', 'Torii', 'Bento'], 'Omamori, belirli bir dilek için kutsandığına inanılan küçük kumaş muskalardır; Budist tapınaklarında da satılır.'),
  ('Batı Afrika\'da Nijerya ve Benin\'de yaşayan, \'orisha\' adı verilen tanrısal varlıklara inanan ve inançları Amerika\'daki birçok geleneği etkilemiş halk hangisidir?', 'Yorubalar', ['Zulular', 'Maasailer', 'Berberiler'], 'Yoruba dini, Olodumare adlı yüce varlık ve orishalara inanır; köle ticaretiyle Amerika\'ya taşınan bu inançlar Santeria ve Candomblé\'yi biçimlendirmiştir.'),
  ('Etiyopya\'da 12-13. yüzyılda kral Lalibela döneminde tek parça kayaya oyulmuş olarak yapılan yapılar hangileridir?', 'Kiliseler', ['Camiler', 'Sinagoglar', 'Saraylar'], 'Lalibela\'daki on bir kaya kilisesi yukarıdan aşağı oyularak yapılmıştır ve UNESCO Dünya Mirası listesindedir.'),
  ('Adı Nikolaos olan bir Rum Ortodoks denizci, hem adaşı hem de denizcilerin koruyucusu sayılan azizin ikonasını teknesinde taşıyor. Hristiyan geleneğinde bu tür azizlere ne ad verilir?', 'Koruyucu aziz', ['Kardinal', 'Havari', 'Peygamber'], 'Katolik ve Ortodoks geleneklerinde kişilerin, şehirlerin ve mesleklerin koruyucu azizleri vardır; örneğin Aziz Nikolaos denizcilerin koruyucusu sayılır.'),
  ('1618-1648 arasında Orta Avrupa\'da Katolik ve Protestan devletler arasında yaşanan ve Vestfalya Barışı ile sona eren savaş hangisidir?', 'Otuz Yıl Savaşları', ['Yüz Yıl Savaşları', 'Güller Savaşı', 'Haçlı Seferleri'], 'Otuz Yıl Savaşları, mezhep çatışması olarak başlayıp Avrupa güçlerinin mücadelesine dönüşmüş; 1648 Vestfalya Barışı her hükümdarın kendi ülkesinin mezhebini belirlemesini pekiştirmiştir.'),
  ('Ortaçağ İspanya\'sında 1478\'de kurulan ve din değiştirenlerin inançlarını denetleyen mahkemeye ne ad verilir?', 'İspanyol Engizisyonu', ['Kutsal İttifak', 'Trento Konsili', 'Cizvit Tarikatı'], 'İspanyol Engizisyonu, Katolik Hükümdarlar Ferdinand ve Isabella döneminde kurulmuş, özellikle Hristiyanlığa geçmiş Yahudi ve Müslümanları denetlemiştir; 1834\'te kaldırılmıştır.'),
  ('Bir öğretmen \'Hinduizmin tek bir kurucusu ve tek bir bağlayıcı kutsal kitabı yoktur\' diyor. Bu ifadeyi en iyi destekleyen bilgi hangisidir?', 'Hinduizmin binlerce yıl içinde Veda, Upanişad, destan ve Purana gibi farklı metinlerle çok sesli gelişmesi', ['Hinduizmin 19. yüzyılda tek bir kişi tarafından kurulması', 'Hinduizmde hiçbir kutsal metin bulunmaması', 'Hinduların yalnız Bhagavad Gita\'yı tanıması'], 'Hinduizm belirli bir kurucuya dayanmaz; Vedalardan destanlara uzanan geniş bir metin geleneği ve birbirinden farklı okullar içerir.'),
  ('Bir araştırmacı, Kudüs\'ün üç İbrahimî din için kutsal olduğunu göstermek istiyor. Hangi üçlü bu amaca en uygun örnekleri sunar?', 'Batı Duvarı, Kutsal Kabir Kilisesi ve Mescid-i Aksa', ['Altın Tapınak, Kâbe ve Vatikan', 'Laleş, Varanasi ve Ise', 'Sina Dağı, Bodh Gaya ve Mekke'], 'Batı Duvarı Yahudilik, Kutsal Kabir Kilisesi Hristiyanlık, Mescid-i Aksa ise İslam için Kudüs\'teki en önemli mekânlardandır.'),
  ('Aşağıdaki dinlerden hangisi kronolojik olarak en yenidir?', 'Bahailik', ['Sihizm', 'Zerdüştlük', 'Caynizm'], 'Bahailik 19. yüzyılda, Sihizm 15-16. yüzyılda ortaya çıkmıştır; Zerdüştlük ve Caynizm ise milattan önceki yüzyıllara uzanır.'),
  ('Hem Hristiyan hem de Müslüman geleneklerde saygıyla anılan, ama Yahudilikte peygamber kabul edilmeyen kişi hangisidir?', 'İsa', ['Musa', 'İbrahim', 'Davud'], 'İsa, Hristiyanlıkta Tanrı\'nın Oğlu, İslam\'da ise peygamber olarak kabul edilir; Yahudilik onu peygamber ya da Mesih olarak tanımaz.'),
  ('Hristiyanlık ve İslam\'daki İsa anlayışlarını karşılaştıran bir öğrencinin yazdıklarından hangisi doğrudur?', 'İki din de İsa\'nın bakire Meryem\'den doğduğunu kabul eder, ancak İslam onu Tanrı\'nın oğlu saymaz', ['İki din de İsa\'yı Tanrı\'nın oğlu olarak kabul eder', 'İslam İsa\'nın varlığını tümüyle reddeder', 'Hristiyanlık İsa\'yı yalnız bir öğretmen sayar'], 'Kur\'an İsa\'nın Meryem\'den babasız doğduğunu ve peygamber olduğunu kabul eder, ancak tanrısallığını ve Teslis\'i reddeder.'),
  ('Bir caminin bakımından, temizliğinden ve kapılarının açılıp kapanmasından sorumlu görevliye geleneksel olarak ne ad verilir?', 'Kayyum', ['Müezzin', 'Hatip', 'Müftü'], 'Kayyum (kayyım), caminin bakım ve temizliğinden sorumlu görevlidir.'),
];
